function connectNetworkDuel(host){if(!('BroadcastChannel'in window)){networkStatus('BroadcastChannel не поддерживается');return}const code=(document.querySelector('#networkRoomCode').value||'AETHER1').trim().toUpperCase();if(networkDuel.channel)networkDuel.channel.close();networkDuel.host=host;networkDuel.room=code;networkDuel.channel=new BroadcastChannel('aether-duel-'+code);networkDuel.channel.onmessage=e=>handleNetworkMessage(e.data);networkStatus(host?'Комната создана · ожидаем соперника':'Подключение к комнате…');netSend({type:host?'host':'join',hero:hero.kind});if(!host)setTimeout(()=>netSend({type:'join',hero:hero.kind}),250)}
