function handleNetworkMessage(msg){if(!msg||msg.room!==networkDuel.room)return;if(msg.type==='host'&&!networkDuel.host){networkDuel.connected=true;networkStatus('Хост найден · запуск матча');netSend({type:'join',hero:hero.kind});setTimeout(startNetworkMatch,300)}else if(msg.type==='join'&&networkDuel.host){networkDuel.connected=true;networkStatus('Соперник подключён · запуск матча');netSend({type:'accept',hero:hero.kind});setTimeout(startNetworkMatch,300)}else if(msg.type==='accept'&&!networkDuel.host){networkDuel.connected=true;setTimeout(startNetworkMatch,200)}else if(msg.type==='state'&&networkDuel.active){networkDuel.remoteX=WORLD.w-msg.x;networkDuel.remoteY=WORLD.h-msg.y;enemy.hp=Math.max(0,msg.hp);enemy.maxHp=msg.maxHp;enemy.dir=(msg.dir||0)+Math.PI;enemy.dead=!!msg.dead;enemy.name=msg.name||'СЕТЕВОЙ СОПЕРНИК';enemy.color=msg.color||'#ff6475'}else if(msg.type==='damage'&&networkDuel.active&&!hero.dead){hurtHero(msg.amount,true,'Сетевой соперник',msg.damageType||'physical');combatImpact(1)}else if(msg.type==='cast'&&networkDuel.active){particles.push({x:enemy.x,y:enemy.y,life:.7,max:.7,type:'botBlast',color:msg.color||enemy.color})}else if(msg.type==='leave'){networkStatus('Соперник отключился');networkDuel.connected=false}}
function updateNetworkDuel(dt){if(!networkDuel.active||!networkDuel.connected)return;if(Number.isFinite(networkDuel.remoteX)){const blend=Math.min(1,dt*14);enemy.x+=(networkDuel.remoteX-enemy.x)*blend;enemy.y+=(networkDuel.remoteY-enemy.y)*blend}networkDuel.syncCd-=dt;if(networkDuel.syncCd<=0){networkDuel.syncCd=.08;netSend({type:'state',x:hero.x,y:hero.y,hp:hero.hp,maxHp:hero.maxHp,dir:hero.dir,dead:hero.dead,name:hero.name,color:hero.color})}}
