function advanceAutoTest(result){const queue=autoTestQueue(),log=JSON.parse(localStorage.getItem('aetherAutoTestLog')||'[]');log.push({mode:autoTest.mode,result,time:Math.round(autoTest.elapsed),kills:stats.kills,deaths:stats.deaths,damage:Math.round(stats.damage)});queue.shift();localStorage.setItem('aetherAutoTestLog',JSON.stringify(log));const backup=localStorage.getItem('aetherAutoTestBackup');if(backup!==null)localStorage.setItem('aetherProfile',backup);localStorage.setItem('aetherAutoTestQueue',JSON.stringify(queue));if(queue.length)setTimeout(()=>location.reload(),500);else{localStorage.removeItem('aetherAutoTestQueue');localStorage.removeItem('aetherAutoTestBackup');localStorage.setItem('aetherAutoTestLastReport',JSON.stringify(log));setTimeout(()=>{location.reload()},700)}}
function updateAutoTest(dt){if(!autoTest.active||autoTest.finishing||gameOver)return;autoTest.elapsed+=dt;const foes=[enemy,...botHeroes.filter(b=>b.team==='red'),...minions.filter(m=>m.team==='red'),...monsters].filter(u=>!u.dead&&u.hp>0),target=foes.sort((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)-Math.hypot(b.x-hero.x,b.y-hero.y))[0];if(target){hero.target=target;const d=Math.hypot(target.x-hero.x,target.y-hero.y);if(d<520){hero.dir=Math.atan2(target.y-hero.y,target.x-hero.x);if(hero.cd.Q<=0)cast('Q');else if(hero.cd.E<=0)cast('E');else if(hero.attackCd<=0)attack()}else hero.moveTarget={x:target.x,y:target.y}}if(gameMode==='hunt'){const pickup=hunt.pickups?.find(p=>p.active);if(pickup&&(hero.huntCarry||0)<3)hero.moveTarget={x:pickup.x,y:pickup.y};else if((hero.huntCarry||0)>=3)hero.moveTarget={...hunt.banks.blue}}if(autoTest.elapsed>=35){autoTest.finishing=true;const win=gameMode==='hunt'?hunt.blue>=hunt.red:gameMode==='skirmish'?skirmish.blue>=skirmish.red:stats.kills>=stats.deaths;setTimeout(()=>advanceAutoTest(win?'PASS':'CHECK'),900);endGame(win)}}
