function localDateId(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function arcadeWeekId(){const d=new Date(),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return localDateId(d)}
function featuredModeFor(dateId){let hash=0;for(const c of dateId)hash=(hash*31+c.charCodeAt(0))|0;return arcadeModes[Math.abs(hash)%arcadeModes.length]}
function ensureArcadeRotation(){const date=localDateId(),week=arcadeWeekId(),featured=featuredModeFor(date);if(!profile.arcadeRotation||profile.arcadeRotation.weekId!==week)profile.arcadeRotation={date,featured,dailyMatches:0,dailyWins:0,dailyClaimed:false,weekId:week,weekly:{matches:0,wins:0,modes:[],claimed:false}};else if(profile.arcadeRotation.date!==date)Object.assign(profile.arcadeRotation,{date,featured,dailyMatches:0,dailyWins:0,dailyClaimed:false});profile.arcadeRotation.weekly??={matches:0,wins:0,modes:[],claimed:false}}
