const modeMasteryThresholds=[0,100,300,650,1100,1800],modeMasteryNames=['НОВИЧОК','БОЕЦ','ЭКСПЕРТ','МАСТЕР','ЛЕГЕНДА','МИФ'];
function modeMasteryTier(xp){let level=0;for(let i=1;i<modeMasteryThresholds.length;i++)if(xp>=modeMasteryThresholds[i])level=i;return{level,name:modeMasteryNames[level],next:modeMasteryThresholds[level+1]||null}}
function grantModeMastery(mode,win,appraisal){profile.modeMastery[mode]??={xp:0,matches:0,wins:0,bestGrade:'D'};ensureArcadeRotation();const m=profile.modeMastery[mode],before=modeMasteryTier(m.xp).level,baseGain=18+(win?22:0)+(appraisal.mvp?8:0)+appraisal.medals.length*2,gain=Math.round(baseGain*(mode===profile.arcadeRotation.featured?1.5:1));m.xp+=gain;m.matches++;if(win)m.wins++;const grades=['D','C','B','A','S','S+'];if(grades.indexOf(appraisal.grade)>grades.indexOf(m.bestGrade))m.bestGrade=appraisal.grade;const after=modeMasteryTier(m.xp).level;for(let level=before+1;level<=after;level++){const key=mode+':'+level;if(!profile.modeMasteryRewards.includes(key)){profile.modeMasteryRewards.push(key);const reward=[0,50,100,175,300,500][level]||0;profile.credits+=reward;announce(`МАСТЕРСТВО РЕЖИМА · ${modeMasteryNames[level]}`);showToast(`Награда режима: +${reward} ◈`)}}}
function renderModeMastery(){ensureArcadeRotation();const list=document.querySelector('#modeMasteryList'),info=document.querySelector('#modeRotationInfo'),a=profile.arcadeRotation,w=a.weekly,[featuredName,featuredColor]=modeMasteryDefs[a.featured]||[a.featured,'#ffd66b'];info.style.setProperty('--featured',featuredColor);info.innerHTML=`<strong>★ РЕЖИМ ДНЯ: ${featuredName}</strong><small>+50% мастерства · первая победа +75 ◈ ${a.dailyClaimed?'✓':''}</small><b>Недельный круг</b><span>Матчи ${Math.min(w.matches,7)}/7 · Победы ${Math.min(w.wins,3)}/3 · Режимы ${Math.min(w.modes.length,4)}/4 ${w.claimed?'· НАГРАДА ПОЛУЧЕНА':'· награда 350 ◈'}</span>`;list.innerHTML='';for(const [id,[name,color]] of Object.entries(modeMasteryDefs)){const m=profile.modeMastery[id]||{xp:0,matches:0,wins:0,bestGrade:'D'},tier=modeMasteryTier(m.xp),base=modeMasteryThresholds[tier.level],progress=tier.next?Math.min(1,(m.xp-base)/(tier.next-base)):1,card=document.createElement('article');card.className='mode-mastery-card';card.style.setProperty('--mode-color',color);card.innerHTML=`<header><strong>${name}</strong><b>${tier.name} · ${m.xp} XP</b></header><small>${m.wins}/${m.matches} побед · лучшая оценка ${m.bestGrade}${tier.next?' · до следующего '+(tier.next-m.xp):' · максимальный ранг'}</small><div class="mode-mastery-bar"><i style="width:${progress*100}%"></i></div>`;list.appendChild(card)}}
