function updateCollection(){collection.querySelectorAll('[data-skin]').forEach(b=>{const id=b.dataset.skin,owned=profile.ownedSkins.includes(id),selected=profile.selectedSkin===id;b.classList.toggle('selected',selected);b.classList.toggle('locked',!owned);const small=b.querySelector('small');small.textContent=selected?'Выбрано':owned?'Нажмите, чтобы выбрать':skins[id].cost+' ◈'})}
document.querySelector('#openCollection').onclick=()=>{updateCollection();collection.classList.remove('hidden')};document.querySelector('#closeCollection').onclick=()=>collection.classList.add('hidden');
const heroCareerMilestones=[{id:'debut',label:'БОЕВОЕ КРЕЩЕНИЕ',key:'games',goal:3,reward:100,mastery:15},{id:'victor',label:'ПОБЕДИТЕЛЬ',key:'wins',goal:5,reward:150,mastery:25},{id:'slayer',label:'ОХОТНИК',key:'kills',goal:50,reward:220,mastery:35},{id:'veteran',label:'ВЕТЕРАН',key:'games',goal:25,reward:300,mastery:50}];
function checkHeroCareer(id){const stats=profile.heroStats[id],claimed=profile.heroCareerRewards[id];for(const m of heroCareerMilestones)if(stats[m.key]>=m.goal&&!claimed.includes(m.id)){claimed.push(m.id);profile.credits+=m.reward;profile.mastery[id]=(profile.mastery[id]||0)+m.mastery;announce(`${heroTypes[id].name} · ${m.label}`);feed(`Этап героя: +${m.reward} ◈ · +${m.mastery} мастерства`,'blue')}}
const heroCareerPanel=document.querySelector('#heroCareerPanel'),heroCareerList=document.querySelector('#heroCareerList');
function renderHeroCareer(){heroCareerList.innerHTML='';for(const [id,h] of Object.entries(heroTypes)){const s=profile.heroStats[id],mastery=profile.mastery[id]||0,tier=masteryTier(mastery),claimed=profile.heroCareerRewards[id],next=heroCareerMilestones.find(m=>!claimed.includes(m.id)),row=document.createElement('div');row.className='hero-career-card';row.style.setProperty('--hero',h.color);row.innerHTML=`<b>${h.name}</b><strong style="color:${tier.color}">${tier.name} · ${mastery}</strong><small>Матчи ${s.games} · Победы ${s.wins} · K/A ${s.kills}/${s.assists}</small><span>Урон за карьеру: ${Math.round(s.damage)}</span>${next?`<i><em style="width:${Math.min(100,s[next.key]/next.goal*100)}%"></em></i><small>${next.label}: ${Math.min(next.goal,s[next.key])}/${next.goal} · ${next.reward} ◈ · ${next.mastery} мастерства</small>`:'<mark>✓ ВСЕ ЭТАПЫ ЗАВЕРШЕНЫ</mark>'}<div class="spec-grid">${heroSpecializations[id].map(spec=>`<button data-hero="${id}" data-spec="${spec[0]}" ${mastery<spec[2]?'disabled':''} class="${activeHeroSpec(id)?.[0]===spec[0]?'active':''}"><b>${spec[1]}</b><small>${mastery<spec[2]?'🔒 '+spec[2]+' мастерства':spec[3]+' · '+specRank(specProgress(id,spec[0])).name+' '+specProgress(id,spec[0]).xp+' XP'}</small></button>`).join('')}</div>`;heroCareerList.appendChild(row)}heroCareerList.querySelectorAll('.spec-grid button:not([disabled])').forEach(btn=>btn.onclick=()=>{profile.heroSpecs[btn.dataset.hero]=btn.dataset.spec;saveProfile();renderHeroCareer();showToast('Специализация выбрана')})}
document.querySelector('#openHeroCareer').onclick=()=>{renderHeroCareer();heroCareerPanel.classList.remove('hidden')};document.querySelector('#closeHeroCareer').onclick=()=>heroCareerPanel.classList.add('hidden');
const factionPanel=document.querySelector('#factionPanel'),factionList=document.querySelector('#factionList');
function renderFaction(){const active=profile.faction?factionDefs[profile.faction]:null;document.querySelector('#factionSummary').textContent=active?`Ваш союз: ${active.name} · смена союза 200 ◈`:'Выберите союз. Первый выбор бесплатный.';factionList.innerHTML='';for(const [id,f] of Object.entries(factionDefs)){const rep=profile.factionRep[id],tier=factionTier(rep),next=tier.level===0?100:tier.level===1?300:tier.level===2?650:null,row=document.createElement('div');row.className='faction-card '+(profile.faction===id?'active':'');row.style.setProperty('--faction',f.color);row.innerHTML=`<b>${f.name}</b><small>${f.desc}</small><strong>${tier.name} · ${rep}${next?' / '+next:''}</strong><i><span style="width:${next?Math.min(100,rep/(next)*100):100}%"></span></i><em>${tier.level>=3?'Награда: облик открыт':tier.level===2?'Следующая награда: союзный облик':`Следующая награда: ${(tier.level+1)*75} ◈`}</em><button ${profile.faction===id?'disabled':''}>${profile.faction===id?'ВЫБРАНО':profile.faction?'СМЕНИТЬ · 200 ◈':'ВСТУПИТЬ'}</button>`;row.querySelector('button').onclick=()=>chooseFaction(id);factionList.appendChild(row)}}
document.querySelector('#openFaction').onclick=()=>{renderFaction();factionPanel.classList.remove('hidden')};document.querySelector('#closeFaction').onclick=()=>factionPanel.classList.add('hidden');
collection.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>{const id=b.dataset.skin,s=skins[id];if(!profile.ownedSkins.includes(id)){if(profile.credits<s.cost){showToast('Недостаточно постоянных кредитов');return}profile.credits-=s.cost;profile.ownedSkins.push(id);feed('Получен облик: '+b.querySelector('strong').textContent);sfx('win')}profile.selectedSkin=id;saveProfile();applySkin()});applySkin();
