function checkAchievements(){for(const a of achievementDefs)if(!profile.achievements.includes(a.id)&&a.value()>=a.goal){profile.achievements.push(a.id);profile.credits+=a.reward;announce('ДОСТИЖЕНИЕ: '+a.title);feed('Награда за достижение: +'+a.reward+' ◈');}saveProfile();renderAchievements()}
