const dailyDefs=[{id:'play',title:'На передовой',desc:'Завершите матчи',goal:2,reward:70},{id:'win',title:'Путь победителя',desc:'Победите в матче',goal:1,reward:90},{id:'kills',title:'Охота начинается',desc:'Уничтожьте вражеских героев',goal:5,reward:80},{id:'towers',title:'Падение бастионов',desc:'Разрушьте сооружения',goal:2,reward:90},{id:'jungle',title:'Зов чащи',desc:'Победите лесные цели',goal:4,reward:75},{id:'runes',title:'Течение эфира',desc:'Захватите речные руны',goal:2,reward:85}];
function dailyKey(){const d=new Date();return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`}
function processFirstWin(win){if(!win||profile.firstWinDate===dailyKey())return false;const today=new Date(),previous=profile.firstWinDate?new Date(profile.firstWinDate.replace(/-/g,'/')):null,yesterday=new Date(today.getFullYear(),today.getMonth(),today.getDate()-1),continued=previous&&previous.getFullYear()===yesterday.getFullYear()&&previous.getMonth()===yesterday.getMonth()&&previous.getDate()===yesterday.getDate();profile.loginWinStreak=continued?profile.loginWinStreak+1:1;profile.bestWinStreak=Math.max(profile.bestWinStreak,profile.loginWinStreak);profile.firstWinDate=dailyKey();profile.credits+=100;grantSeasonXp(40);grantFactionRep(30);announce(`ПЕРВАЯ ПОБЕДА ДНЯ · СЕРИЯ ${profile.loginWinStreak}`);feed('Ежедневная награда: +100 ◈ · +40 опыта пути','blue');return true}
function ensureDaily(){const key=dailyKey();if(profile.daily?.date===key&&Array.isArray(profile.daily.missions))return;let seed=[...key].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,2166136261),pool=[...dailyDefs];for(let i=pool.length-1;i>0;i--){seed=(seed*1664525+1013904223)>>>0;const j=seed%(i+1);[pool[i],pool[j]]=[pool[j],pool[i]]}profile.daily={date:key,missions:pool.slice(0,3).map(x=>({id:x.id,progress:0,claimed:false}))};saveProfile()}
function updateDaily(result){ensureDaily();const gain={play:1,win:result.win?1:0,kills:result.kills,towers:result.towers,jungle:result.monsters,runes:result.runes};for(const m of profile.daily.missions){const def=dailyDefs.find(x=>x.id===m.id);m.progress=Math.min(def.goal,(m.progress||0)+(gain[m.id]||0))}saveProfile()}
function grantSeasonXp(amount){const s=profile.season;if(s.level>=s.maxLevel)return;s.xp+=amount;while(s.xp>=100&&s.level<s.maxLevel){s.xp-=100;s.level++;const reward=s.level%5===0?150:45;profile.credits+=reward;announce(`ЭФИРНЫЙ ПУТЬ · УРОВЕНЬ ${s.level}`);feed(`Награда пути: +${reward} ◈`,'blue')}if(s.level>=s.maxLevel)s.xp=0}
function claimDaily(id){ensureDaily();const m=profile.daily.missions.find(x=>x.id===id),def=dailyDefs.find(x=>x.id===id);if(!m||!def||m.claimed||m.progress<def.goal)return;m.claimed=true;profile.dailyCompleted++;profile.credits+=def.reward;grantSeasonXp(20);saveProfile();announce('ЗАДАНИЕ ДНЯ ВЫПОЛНЕНО');feed(`${def.title}: +${def.reward} ◈`,'blue');renderDaily();renderProfile()}
