function renderDaily(){ensureDaily();const s=profile.season,season=document.querySelector('#seasonTrack');season.innerHTML=`<b>ЭФИРНЫЙ ПУТЬ · УРОВЕНЬ ${s.level}/${s.maxLevel}</b><small>${s.level>=s.maxLevel?'Путь завершён':`${s.xp}/100 опыта · следующая награда ${((s.level+1)%5===0)?150:45} ◈`}</small><i><span style="width:${s.level>=s.maxLevel?100:s.xp}%"></span></i>`;const now=new Date(),midnight=new Date(now.getFullYear(),now.getMonth(),now.getDate()+1),left=Math.max(0,midnight-now),h=Math.floor(left/3600000),m=Math.floor(left%3600000/60000);document.querySelector('#dailyTimer').innerHTML=`Обновление через ${h} ч ${m} мин · выполнено всего: ${profile.dailyCompleted}<br><b>${profile.firstWinDate===dailyKey()?'✓ Первая победа дня получена':'Первая победа дня: +100 ◈ и +40 опыта пути'}</b> · серия ${profile.loginWinStreak}, рекорд ${profile.bestWinStreak}`;dailyList.innerHTML='';for(const mission of profile.daily.missions){const def=dailyDefs.find(x=>x.id===mission.id),done=mission.progress>=def.goal,row=document.createElement('div');row.className='achievement '+(mission.claimed?'done':'');row.innerHTML=`<strong>${mission.claimed?'✓ ':''}${def.title}</strong><small>${def.desc}</small><span>${mission.progress}/${def.goal} · ${def.reward} ◈</span><button ${done&&!mission.claimed?'':'disabled'}>${mission.claimed?'ПОЛУЧЕНО':done?'ЗАБРАТЬ':'В ПРОЦЕССЕ'}</button>`;row.querySelector('button').onclick=()=>claimDaily(mission.id);dailyList.appendChild(row)}}
