function scoreExperimentArm(p){const q=p?.matches||0;if(!q)return null;const duration=p.durationSum/q,stall=p.stallMatches/q*100,limit=p.limitFinishes/q*100,kills=p.killsSum/q,towers=p.towersSum/q,dragons=p.dragonsSum/q,killGap=p.killGapSum/q,close=p.closeMatches/q*100,blueWinRate=p.blueWins/q*100,coreMargin=p.coreMarginSum/q,blowouts=p.blowoutMatches/q*100,paceScore=Math.abs(duration-570)/3+stall*1.2+limit*1.5,qualityScore=(kills<8?(8-kills)*3:kills>26?(kills-26)*1.5:0)+(towers<2?(2-towers)*10:0)+(dragons<.5?(.5-dragons)*14:0)+killGap*3+Math.max(0,50-close)*.35+Math.abs(blueWinRate-50)*.6+coreMargin*.25+blowouts*.5;return{matches:q,score:Math.round(paceScore+qualityScore),paceScore:Math.round(paceScore),qualityScore:Math.round(qualityScore),duration:Math.round(duration),blueWinRate:Math.round(blueWinRate),blowouts:Math.round(blowouts),blind:Math.round((p.blindMatches||0)/q*100),matchQuality:p.assessmentMatches?Math.round((p.qualityScoreSum||0)/p.assessmentMatches):null,highQuality:p.assessmentMatches?Math.round((p.highQualityMatches||0)/p.assessmentMatches*100):null}}
function compareExperiment(challenger){const names={fasterTowers:'Быстрее башни',earlyFights:'Больше ранних боёв',lessStall:'Меньше антизастоя'},e=profile.pacingStats.experiments?.[challenger],standard=scoreExperimentArm(e?.standard),test=scoreExperimentArm(e?.challenger);if(!standard||!test||standard.matches<3||test.matches<3)return{ready:false,challenger,text:`Эксперимент «${names[challenger]||challenger}»: нужно по 3 матча на группу · ${standard?.matches||0}/3 и ${test?.matches||0}/3.`};const gap=Math.abs(standard.score-test.score),winner=standard.score<=test.score?'standard':challenger,winnerName=winner==='standard'?'Стандарт':names[challenger],sample=Math.min(standard.matches,test.matches),equivalent=sample>=10&&gap<5,stop=equivalent||sample>=8&&gap>=25,confidence=sample>=8&&gap>=25?'высокая':sample>=5&&gap>=10?'средняя':'низкая';return{ready:true,challenger,standard,test,winner,winnerName,gap,confidence,stop,equivalent,text:equivalent?`Результаты эквивалентны: разрыв ${gap}. Эксперимент можно завершить.`:`Лидер «${winnerName}», разрыв ${gap}, уверенность ${confidence}.${stop?' Достаточно данных для остановки.':' Продолжайте сбор выборки.'}`}}
