function repairHeroCombatState(){let repairs=0;if(!Number.isFinite(hero.maxHp)||hero.maxHp<=0){hero.maxHp=100;repairs++}if(!Number.isFinite(hero.hp)){hero.hp=hero.maxHp;repairs++}else{const hp=Math.max(0,Math.min(hero.maxHp,hero.hp));if(hp!==hero.hp){hero.hp=hp;repairs++}}if(!Number.isFinite(hero.maxMana)||hero.maxMana<=0){hero.maxMana=100;repairs++}if(!Number.isFinite(hero.mana)){hero.mana=hero.maxMana;repairs++}else{const mana=Math.max(0,Math.min(hero.maxMana,hero.mana));if(mana!==hero.mana){hero.mana=mana;repairs++}}for(const key of ['shield','stun','slow','ccFatigue','attackCd'])if(!Number.isFinite(hero[key])||hero[key]<0){hero[key]=0;repairs++}if(!Number.isFinite(hero.attackSpeed)||hero.attackSpeed<=0){hero.attackSpeed=1;repairs++}else if(hero.attackSpeed>10){hero.attackSpeed=10;repairs++}if(!hero.cd||typeof hero.cd!=='object'){hero.cd={Q:0,W:0,E:0,R:0};repairs++}else for(const key of ['Q','W','E','R'])if(!Number.isFinite(hero.cd[key])||hero.cd[key]<0){hero.cd[key]=0;repairs++}if(repairs){combatIntegrityTelemetry.heroStateRepairs+=repairs;if(runtimeDiagnostics.invalidState.length<30)runtimeDiagnostics.invalidState.push({time:Date.now(),system:'heroCombatState',repairs})}return repairs}
function syncCriticalHealthUi(){const active=!!(running&&!gameOver&&!hero.dead&&Number.isFinite(hero.hp)&&Number.isFinite(hero.maxHp)&&hero.maxHp>0&&hero.hp/hero.maxHp<=.25);if(syncCriticalHealthUi.last===active)return;syncCriticalHealthUi.last=active;(syncCriticalHealthUi.shell??=document.querySelector('#game-shell'))?.classList.toggle('critical-health',active)}
function updateControlHud(){const hud=updateControlHud.node??=document.querySelector('#controlHud');if(!hud)return;const stun=Number.isFinite(hero.stun)?Math.max(0,hero.stun):0,slow=Number.isFinite(hero.slow)?Math.max(0,hero.slow):0,kind=hero.dead||!running||gameOver?null:stun>0?'stun':slow>0?'slow':null,remaining=kind==='stun'?stun:kind==='slow'?slow:0,queued=kind?(hero.skillBuffer?.key||(hero.attackBuffer?'АТАКА':null)):null,queuedNote=queued?(kind==='stun'?`${queued} ВЫПОЛНИТСЯ ПОСЛЕ КОНТРОЛЯ`:`${queued} ПОДГОТОВЛЕНА`):'',label=kind?`${kind==='stun'?'ОГЛУШЕНИЕ':'ЗАМЕДЛЕНИЕ'} ${remaining.toFixed(1)}с${queuedNote?' · '+queuedNote:''}`:'';if(updateControlHud.lastLabel===label)return;updateControlHud.lastLabel=label;hud.classList.toggle('hidden',!kind);hud.classList.toggle('stun',kind==='stun');hud.classList.toggle('slow',kind==='slow');hud.innerHTML=kind?`<b>${kind==='stun'?'ОГЛУШЕНИЕ':'ЗАМЕДЛЕНИЕ'} · ${remaining.toFixed(1)}с</b>${queuedNote?`<small class="queued">${queuedNote}</small>`:''}${hero.ccFatigue>0?'<small>УСТОЙЧИВОСТЬ К ПОВТОРНОМУ КОНТРОЛЮ</small>':''}`:'';hud.setAttribute('aria-label',label||'Контроль отсутствует')}
function playerDamageFeedback(amount,type='physical'){if(!Number.isFinite(amount)||amount<=0||!hero?.maxHp)return;const now=performance.now();if(now-(playerDamageFeedback.last||0)<90){combatIntegrityTelemetry.damageFeedbackThrottled++;return}playerDamageFeedback.last=now;const shell=playerDamageFeedback.shell??=document.querySelector('#game-shell');if(!shell?.animate)return;const ratio=Math.min(1,amount/hero.maxHp),color=type==='magic'?'161,99,255':type==='true'?'255,255,255':'255,66,86',alpha=.16+ratio*.34;playerDamageFeedback.animation?.cancel();playerDamageFeedback.animation=shell.animate([{boxShadow:'inset 0 0 0 0 rgba('+color+',0)'},{boxShadow:`inset 0 0 ${40+ratio*90}px ${8+ratio*24}px rgba(${color},${alpha})`,offset:.28},{boxShadow:'inset 0 0 0 0 rgba('+color+',0)'}],{duration:ratio>.2?260:180,easing:'ease-out'});combatIntegrityTelemetry.damageFeedbacks++}
function combatImpact(power=1){power=Number.isFinite(power)?Math.max(0,Math.min(2,power)):1;if(options.shake)shake=Math.max(shake,.08+power*.07);if(!options.reducedMotion)hitStop=Math.max(hitStop,.018+power*.014);if(options.reducedMotion)return;const shell=combatImpact.shell??=(document.querySelector('#game-shell'));if(!shell)return;if(typeof shell.animate==='function'){combatImpact.flash?.cancel();combatImpact.flash=shell.animate([{filter:'brightness(1) saturate(1)'},{filter:`brightness(${1.08+power*.07}) saturate(${1.06+power*.08})`,offset:.5},{filter:'brightness(1) saturate(1)'}],{duration:100,easing:'linear'})}else{shell.classList.add('impact-flash');clearTimeout(combatImpact.timer);combatImpact.timer=setTimeout(()=>shell.classList.remove('impact-flash'),110)}}
