function activeItems(){return [...hero.upgradedItems]}
function cycleActiveItem(){const list=activeItems();if(!list.length){showToast('Сначала улучшите предмет до легендарного');return}hero.activeItemIndex=(hero.activeItemIndex+1)%list.length;showToast('Активный предмет: '+itemNames[list[hero.activeItemIndex]])}
function useActiveItem(){if(!running||paused||hero.dead)return;const list=activeItems();if(!list.length){showToast('Нет легендарного активного предмета');return}hero.activeItemIndex%=list.length;const id=list[hero.activeItemIndex],cd=hero.itemActiveCd[id]||0;if(cd>0){showToast(itemNames[id]+': '+Math.ceil(cd)+'с');return}if(id==='aegis'){hero.shield=Math.max(hero.shield,5);hero.itemActiveCd[id]=48;floatText(hero.x,hero.y-52,'ЭГИДА: БАРЬЕР','#75e9ff');recordTradeDefense('Эгида')}else if(id==='blade'){const t=validTarget(hero.target,380)?hero.target:null;if(!t){showToast('Для Клинка нужна цель');return}const a=Math.atan2(t.y-hero.y,t.x-hero.x);hero.x=t.x-Math.cos(a)*75;hero.y=t.y-Math.sin(a)*75;const dmg=outgoingDamage(t,75,'physical');t.hp=Math.max(0,t.hp-dmg);stats.damage+=dmg;floatText(t.x,t.y-45,'РАССЕЧЕНИЕ −'+Math.round(dmg),'#ffcf62');if(t.hp<=0)grantKill(t);hero.itemActiveCd[id]=38}else if(id==='core'){const gain=Math.round(hero.maxMana*.45);hero.mana=Math.min(hero.maxMana,hero.mana+gain);hero.itemActiveCd[id]=32;floatText(hero.x,hero.y-45,'ЭФИР +'+gain,'#6db8ff')}else if(id==='boots'){hero.itemSprint=6;hero.itemActiveCd[id]=42;floatText(hero.x,hero.y-45,'ФАЗОВЫЙ БЕГ','#78dfff')}else if(id==='fang'){const heal=Math.round((hero.maxHp-hero.hp)*.5+35);hero.hp=Math.min(hero.maxHp,hero.hp+heal);hero.itemActiveCd[id]=45;floatText(hero.x,hero.y-45,'КРОВАВАЯ ЖАЖДА +'+heal,'#ff6688')}else if(id==='chrono'){for(const k of ['Q','W','E'])hero.cd[k]*=.55;hero.itemActiveCd[id]=52;floatText(hero.x,hero.y-45,'СБРОС ВРЕМЕНИ','#b58cff')}particles.push({x:hero.x,y:hero.y,life:.8,max:.8,type:'nova'});sfx('cast');haptic([18,12,25])}
function usePotion(){if(!running||paused||hero.dead)return;if(hero.potionCd>0){showToast('Эликсир ещё восстанавливается');return}if(hero.potions<=0){showToast('Нет эликсиров');return}const controlled=hero.stun>0||hero.slow>0;if(hero.hp>=hero.maxHp&&!controlled){showToast('Здоровье уже полное');return}hero.potions--;hero.potionCd=12;const heal=Math.min(75,hero.maxHp-hero.hp);hero.hp+=heal;hero.stun=0;hero.slow=0;if(heal>0)floatText(hero.x,hero.y-38,'+'+Math.round(heal),'#62ed94');if(controlled)floatText(hero.x,hero.y-56,'ОЧИЩЕНИЕ','#f7f0a5');particles.push({x:hero.x,y:hero.y,life:.7,max:.7,type:'wardPulse'});recordTradeDefense('Зелье');sfx('win');haptic([15,20,15])}
function baseAction(){if(!running||hero.dead||paused)return;if(inBlueShopRange()){updateShopRecommendations();shop.classList.toggle('hidden');return}if(hero.recall>0){hero.recall=0;showToast('Возвращение отменено');return}hero.moveTarget=null;hero.recall=3.5;showToast('Возвращение на базу…');sfx('cast')}
function cancelRecall(){if(hero.recall>0){hero.recall=0;if(options.hints)showToast('Возвращение прервано')}if(hero.teleportChannel>0){hero.teleportChannel=0;hero.teleportTarget=null;if(options.hints)showToast('Телепортация прервана')}}
function startTeleport(){if(!running||paused||hero.dead||hero.stun>0)return;if(hero.teleportCd>0){showToast('Телепорт ещё восстанавливается');return}const available=towers.filter(t=>t.team==='blue'&&t.hp>0);if(!available.length){showToast('Нет доступных союзных башен');return}let target;if(coarsePointer||padInput.connected)target=available.sort((a,b)=>Math.hypot(b.x-210,b.y-1580)-Math.hypot(a.x-210,a.y-1580))[0];else{const wx=mouse.x+cam.x,wy=mouse.y+cam.y;target=available.sort((a,b)=>Math.hypot(a.x-wx,a.y-wy)-Math.hypot(b.x-wx,b.y-wy))[0]}if(Math.hypot(target.x-hero.x,target.y-hero.y)<220){showToast('Вы уже рядом с этой башней');return}hero.recall=0;hero.teleportTarget=target;hero.teleportChannel=3.5;hero.moveTarget=null;hero.attackMove=false;hero.attackMovePoint=null;floatText(hero.x,hero.y-55,'КАНАЛ ТЕЛЕПОРТА','#b78cff');showToast('Не двигайтесь и не получайте урон · 3,5 сек.');sfx('cast')}
function showToast(s){toast.textContent=s;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),1200)}
