function activeHeroSpec(id=hero.kind){const list=heroSpecializations[id]||[],mastery=profile.mastery[id]||0,chosen=profile.heroSpecs[id],valid=list.find(s=>s[0]===chosen&&mastery>=s[2]);return valid||list[0]}
const specThresholds=[0,100,250,500,900],specRanks=['УЧЕНИК','АДЕПТ','ЭКСПЕРТ','МАЭСТРО','ГРАНДМАСТЕР'];
function specProgress(id=hero.kind,specId=activeHeroSpec(id)?.[0]){profile.specProgress[id]??={};profile.specProgress[id][specId]??={xp:0,matches:0,wins:0};return profile.specProgress[id][specId]}
function specRank(data){let level=0;for(let i=1;i<specThresholds.length;i++)if(data.xp>=specThresholds[i])level=i;return{level,name:specRanks[level],next:specThresholds[level+1]||null}}
function grantSpecProgress(win,appraisal){const spec=activeHeroSpec(),data=specProgress(hero.kind,spec[0]),before=specRank(data).level,gain=20+(win?20:0)+(appraisal.mvp?10:0)+appraisal.medals.length*2;data.xp+=gain;data.matches++;if(win)data.wins++;const after=specRank(data).level;for(let level=before+1;level<=after;level++){const key=`${hero.kind}:${spec[0]}:${level}`;if(!profile.specRewards.includes(key)){profile.specRewards.push(key);const reward=[0,60,110,180,300][level];profile.credits+=reward;announce(`${spec[1]} · ${specRanks[level]} · +${reward} ◈`)}}return gain}
function applySpecMilestone(level){if(hero.specMilestones?.includes(level))return;hero.specMilestones??=[];hero.specMilestones.push(level);const effect=activeHeroSpec()?.[4];if(level===6){if(effect==='tank'){hero.armor+=7;hero.tenacity+=.1}else if(effect==='assault'||effect==='hybrid'){hero.damage=Math.round(hero.damage*1.08)}else if(effect==='support'){hero.healPower*=1.12;hero.cdr+=.04}else if(effect==='caster'||effect==='focus'){hero.abilityPower*=1.12;hero.maxMana+=30}else if(effect==='slayer'){hero.armorPen+=8;hero.lifesteal+=.05}else if(effect==='swift'){hero.baseSpeed+=18;hero.attackSpeed*=1.08}else if(effect==='ultimate'){hero.ultPower*=1.16;hero.ultCdr*=.88}}else if(level===10){if(effect==='tank'){hero.maxHp=Math.round(hero.maxHp*1.1);hero.hp+=hero.maxHp*.1}else if(effect==='support'){hero.healPower*=1.15;hero.maxHp=Math.round(hero.maxHp*1.06)}else if(effect==='slayer'||effect==='assault'){hero.executePower+=.06;hero.damage=Math.round(hero.damage*1.06)}else if(effect==='ultimate'){hero.ultPower*=1.2;hero.ultCdr*=.82}else{hero.abilityPower*=1.12;hero.cdr+=.05}}announce(`${activeHeroSpec()?.[1]} · ${level===6?'РАЗВИТИЕ':'ВЫСШАЯ ФОРМА'}`);particles.push({x:hero.x,y:hero.y,life:1,max:1,type:'nova'})}
function applyHeroSpecialization(){const spec=activeHeroSpec(),effect=spec?.[4];hero.activeSpec=spec?.[0]||null;if(effect==='tank'){hero.maxHp=Math.round(hero.maxHp*1.14);hero.hp=hero.maxHp;hero.armor+=8;hero.resist+=5}else if(effect==='assault'){hero.damage=Math.round(hero.damage*1.1);hero.baseSpeed*=1.06;hero.speed=hero.baseSpeed}else if(effect==='support'){hero.healPower*=1.18;hero.maxHp=Math.round(hero.maxHp*1.06);hero.hp=hero.maxHp;hero.shieldPower=1.2}else if(effect==='caster'){hero.abilityPower*=1.14;hero.cdr+=.08}else if(effect==='slayer'){hero.damage=Math.round(hero.damage*1.08);hero.armorPen+=10;hero.lifesteal+=.08}else if(effect==='focus'){hero.maxMana=Math.round(hero.maxMana*1.22);hero.mana=hero.maxMana;hero.cdr+=.1}else if(effect==='hybrid'){hero.damage=Math.round(hero.damage*1.06);hero.abilityPower*=1.1}else if(effect==='swift'){hero.baseSpeed*=1.1;hero.speed=hero.baseSpeed;hero.attackSpeed*=1.12}else if(effect==='ultimate'){hero.ultPower*=1.22;hero.ultCdr*=.82}const proficiency=specRank(specProgress(hero.kind,spec[0])).level;if(proficiency){const scale=1+proficiency*.012;hero.maxHp=Math.round(hero.maxHp*scale);hero.hp=hero.maxHp;hero.damage=Math.round(hero.damage*scale);hero.abilityPower*=scale;hero.healPower*=scale}hero.specMilestones=[];feed(`Специализация: ${spec?.[1]||'базовая'} · ${specRanks[proficiency]}`)}
