const runeForgeCosts=[80,180,320];
function runeResonance(ids=profile.equippedRunes){if(ids.length!==2)return null;return runeResonances[[...ids].sort().join('|')]||null}
function saveRuneLoadout(index){profile.runeLoadouts[index]=[...profile.equippedRunes];saveProfile();renderRuneForge();showToast(`Комплект рун ${index+1} сохранён`)}
function loadRuneLoadout(index){const set=profile.runeLoadouts[index];if(!set){showToast('Этот комплект пуст');return}profile.equippedRunes=set.filter(id=>runeLevel(id)>0).slice(0,2);saveProfile();renderRuneForge();showToast(`Комплект рун ${index+1} экипирован`)}
function runeLevel(id){return Math.max(0,Math.min(4,profile.runeForge[id]||0))}
function upgradeRune(id){const level=runeLevel(id);if(!runeForgeDefs[id]||level>=4)return;if(level===3){if(profile.runeDust<500||profile.runeCores<3){showToast('Пробуждение требует 500 ✧ и 3 ядра Стража');return}profile.runeDust-=500;profile.runeCores-=3;profile.runeForge[id]=4;saveProfile();renderRuneForge();announce(`ВЕЧНАЯ РУНА ПРОБУЖДЕНА · ${runeForgeDefs[id].name}`);sfx('win');return}const cost=runeForgeCosts[level];if(profile.runeDust<cost){showToast(`Нужно ${cost} рунической пыли`);return}profile.runeDust-=cost;profile.runeForge[id]=level+1;saveProfile();renderRuneForge();sfx('buy');showToast(`${runeForgeDefs[id].name} · уровень ${level+1}`)}
function toggleRune(id){if(runeLevel(id)<=0)return;const equipped=profile.equippedRunes,index=equipped.indexOf(id);if(index>=0)equipped.splice(index,1);else if(equipped.length>=2){showToast('Можно экипировать только две руны');return}else equipped.push(id);saveProfile();renderRuneForge()}
function renderRuneForge(){const box=document.querySelector('#runeForgeList'),summary=document.querySelector('#runeForgeSummary');const resonance=runeResonance();summary.innerHTML=`Руническая пыль: <b>${profile.runeDust} ✧</b> · ядра Стража: <b>${profile.runeCores} ◆</b> · экипировано ${profile.equippedRunes.length}/2${resonance?`<mark style="color:${resonance.color}">${resonance.name} · ${resonance.desc}</mark>`:''}<span class="rune-loadouts">${profile.runeLoadouts.map((set,i)=>`<button data-rune-load="${i}">${i+1} ${set?'НАДЕТЬ':'ПУСТО'}</button><button data-rune-save="${i}">↧</button>`).join('')}</span>`;box.innerHTML='';for(const [id,r] of Object.entries(runeForgeDefs)){const level=runeLevel(id),equipped=profile.equippedRunes.includes(id),row=document.createElement('article');row.className='rune-forge-card'+(equipped?' equipped':'')+(level===4?' awakened':'');row.style.setProperty('--rune',r.color);row.innerHTML=`<i>${r.icon}</i><div><b>${r.name}</b><small>${r.desc} · ур. ${level}/4</small><span>${level===4?'✦ ПРОБУЖДЕНА · уникальный эффект':level?`Сила ${level*4}%`:'Не создана'}</span></div><button data-equip="${id}" ${level?'':'disabled'}>${equipped?'СНЯТЬ':'НАДЕТЬ'}</button><button data-upgrade="${id}" ${level>=4?'disabled':''}>${level>=4?'МАКС.':level===3?'ПРОБУДИТЬ · 500 ✧ + 3 ◆':`УЛУЧШИТЬ · ${runeForgeCosts[level]} ✧`}</button>`;box.appendChild(row)}box.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>toggleRune(b.dataset.equip));box.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>upgradeRune(b.dataset.upgrade));summary.querySelectorAll('[data-rune-load]').forEach(b=>b.onclick=()=>loadRuneLoadout(+b.dataset.runeLoad));summary.querySelectorAll('[data-rune-save]').forEach(b=>b.onclick=()=>saveRuneLoadout(+b.dataset.runeSave))}
function applyEquippedRunes(){hero.activeRunes=[];for(const id of profile.equippedRunes.slice(0,2)){const level=runeLevel(id);if(!level)continue;hero.activeRunes.push(id);const power=level*.04;if(id==='heart'){hero.maxHp=Math.round(hero.maxHp*(1+power));hero.hp=hero.maxHp}else if(id==='blade')hero.damage=Math.round(hero.damage*(1+power));else if(id==='hourglass')hero.cdr+=level*.035;else if(id==='boots'){hero.baseSpeed*=1+power;hero.speed=hero.baseSpeed}else if(id==='lens')hero.abilityPower*=1+power;else if(id==='chalice'){hero.healPower*=1+power;hero.lifesteal+=level*.025}else if(id==='crown'){hero.ultPower*=1+level*.06;hero.ultCdr*=1-level*.04}else if(id==='magnet'){hero.gold+=level*120;hero.junglePower*=1+level*.06}if(level===4){if(id==='heart'){hero.armor+=8;hero.resist+=6}else if(id==='blade')hero.executePower+=.05;else if(id==='hourglass')hero.cdr+=.04;else if(id==='boots')hero.attackSpeed*=1.1;else if(id==='lens')hero.magicPen+=10;else if(id==='chalice'){hero.healPower*=1.1;hero.lifesteal+=.05}else if(id==='crown'){hero.ultPower*=1.12;hero.ultCdr*=.9}else if(id==='magnet'){hero.gold+=300;hero.junglePower*=1.12}}}const resonance=runeResonance(hero.activeRunes);const perfect=hero.activeRunes.length===2&&hero.activeRunes.every(id=>runeLevel(id)===4);hero.runeResonance=resonance?resonance.name+(perfect?' · СОВЕРШЕННЫЙ':''):null;if(resonance){resonance.apply();if(perfect){hero.maxHp=Math.round(hero.maxHp*1.03);hero.hp=hero.maxHp;hero.damage=Math.round(hero.damage*1.03);hero.abilityPower*=1.03;hero.healPower*=1.03}const key=[...hero.activeRunes].sort().join('|');if(!profile.runeResonancesSeen.includes(key))profile.runeResonancesSeen.push(key)}if(hero.activeRunes.length)feed('Вечные руны: '+hero.activeRunes.map(id=>runeForgeDefs[id].name).join(' · ')+(resonance?' · '+resonance.name:''))}
