function coopDamage(b,target,amount,type='physical'){if(!target)return;const before=target.hp;if(target===enemy||target.isBot)botUltimateDamage(b,target,amount,type);else{target.hp=Math.max(0,target.hp-amount);floatText(target.x,target.y-32,'−'+Math.round(amount),'#ffb078');if(target.hp<=0){if(target.kind||isStructure(target)){grantKill(target)}else target.dead=!!target.team}}if(before>0&&target.hp<=0){stats.coopKills++;feed(`${b.name} (ИГРОК 2) уничтожил ${target.name||'цель'}`,'blue')}}
function coopBotAction(action){const b=coopBot();if(!b||b.dead||!b.playerControlled)return;const target=coopNearestTarget(b,action==='ult'?360:300);if(action==='attack'&&b.cd<=0){if(!target){showToast('Игрок 2: нет цели');return}b.cd=.65;coopDamage(b,target,b.damage*(b.awakening>0?1.2:1));particles.push({x:b.x,y:b.y,tx:target.x,ty:target.y,life:.18,max:.18,type:'minionShot',target})}else if(action==='skill'&&b.abilityCd<=0){b.abilityCd=6;damageAreaTeam(b,'red',b.x,b.y,125,42*b.abilityPower);particles.push({x:b.x,y:b.y,life:.7,max:.7,type:'botBlast',color:b.color});floatText(b.x,b.y-48,'НАВЫК ИГРОКА 2',b.color)}else if(action==='dash'&&b.sigCd<=0){b.sigCd=7;const n=Math.hypot(coopPad.aimX,coopPad.aimY)||1;b.x+=coopPad.aimX/n*150;b.y+=coopPad.aimY/n*150;particles.push({x:b.x,y:b.y,a:Math.random()*6.28,life:.55,type:'dash'})}else if(action==='ult'&&b.level>=6&&b.ultCd<=0){b.ultCd=20;if(b.role==='ПОДДЕРЖКА'){for(const ally of [hero,...botHeroes.filter(x=>x.team==='blue')])if(!ally.dead&&Math.hypot(ally.x-b.x,ally.y-b.y)<350)ally.hp=Math.min(ally.maxHp,ally.hp+ally.maxHp*.25)}else for(const foe of [enemy,...botHeroes.filter(x=>x.team==='red'),...monsters])if(!foe.dead&&foe.hp>0&&Math.hypot(foe.x-b.x,foe.y-b.y)<350)coopDamage(b,foe,75*b.abilityPower,'magic');particles.push({x:b.x,y:b.y,life:1,max:1,type:'nova'});announce(b.name+' · УЛЬТИМЕЙТ ИГРОКА 2')}}
function damageAreaTeam(source,enemyTeam,x,y,r,amount){for(const u of [enemy,...botHeroes,...minions,...monsters])if(!u.dead&&u.hp>0&&u.team!==source.team&&Math.hypot(u.x-x,u.y-y)<r+(u.r||15))coopDamage(source,u,amount,'magic')}
function updateCoopBot(b,dt,speed){let dx=coopPad.x,dy=coopPad.y,n=Math.hypot(dx,dy),distance=Math.hypot(b.x-hero.x,b.y-hero.y);if(distance>720){dx=hero.x-b.x;dy=hero.y-b.y;n=Math.hypot(dx,dy);b.state='ВОЗВРАЩЕНИЕ К ИГРОКУ 1'}else b.state='ИГРОК 2';if(n>.15){dx/=n;dy/=n;b.x=Math.max(80,Math.min(WORLD.w-80,b.x+dx*speed*dt));b.y=Math.max(80,Math.min(WORLD.h-80,b.y+dy*speed*dt));b.dir=Math.atan2(dy,dx)}}
function pollGamepad(){const p=[...(navigator.getGamepads?.()||[])].find(Boolean);if(!p){padInput.x=padInput.y=0;coopPad.x=coopPad.y=0;padInput.connected=false;return}padInput.connected=true;const dz=.2,axis=v=>Math.abs(v)>dz?v:0;padInput.x=axis(p.axes[0]||0);padInput.y=axis(p.axes[1]||0);const ax=axis(p.axes[2]||0),ay=axis(p.axes[3]||0);padInput.aimActive=!!(ax||ay);if(padInput.aimActive)hero.dir=Math.atan2(ay,ax);const pressed=p.buttons.map(b=>b.pressed),edge=i=>pressed[i]&&!padInput.prev[i];if(gamepadMode==='coop'&&running){if(edge(9)){togglePause();padInput.prev=pressed;return}padInput.x=padInput.y=0;coopPad.x=axis(p.axes[0]||0);coopPad.y=axis(p.axes[1]||0);if(ax||ay){coopPad.aimX=ax;coopPad.aimY=ay}if(edge(0))coopBotAction('attack');if(edge(1))coopBotAction('dash');if(edge(2))coopBotAction('skill');if(edge(3))coopBotAction('ult');if(edge(12)){const b=coopBot();if(b&&b.wardCd<=0){wards.push({x:b.x+coopPad.aimX*150,y:b.y+coopPad.aimY*150,life:75,team:'blue',kind:'ward',name:'ТОТЕМ ИГРОКА 2',r:10,hp:3,maxHp:3,dead:false,revealed:99,disabled:0});b.wardCd=35;showToast('Игрок 2 установил тотем')}}if(edge(13)){const b=coopBot();if(b)placeTypedPing('move',b.x,b.y)}showScore=!!pressed[8]||!!keys.Tab;padInput.prev=pressed;return}if(edge(9)){if(!cancelBufferedInputs())togglePause();padInput.prev=pressed;return}if(edge(0))requestAttack();if(edge(1))requestCast('E');if(edge(2))requestCast('Q');if(edge(3))requestCast('W');if(edge(4))usePotion();if(edge(5))requestCast('R');if(edge(6))baseAction();if(edge(7))startTeleport();if(edge(10))activateAwakening();if(edge(11))cycleHeroTarget();if(edge(12))placeWard(hero.x+Math.cos(hero.dir)*180,hero.y+Math.sin(hero.dir)*180);if(edge(13))placePing(hero.x+Math.cos(hero.dir)*500,hero.y+Math.sin(hero.dir)*500);if(edge(14))useSmite();if(edge(15))useFlash();showScore=!!pressed[8]||!!keys.Tab;padInput.prev=pressed}
function triggerBoundAction(action,e){if(!action)return;if(action.startsWith('move')){e.preventDefault();clearAttackBuffer('movement');return}if(action==='attack'){e.preventDefault();requestAttack()}else if(['Q','W','E','R'].includes(action)&&!e.repeat)requestCast(action);else if(action==='recall'&&!e.repeat)baseAction();else if(action==='flash'&&!e.repeat)useFlash();else if(action==='summoner'&&!e.repeat)useSmite();else if(action==='teleport'&&!e.repeat)startTeleport();else if(action==='ping'&&!e.repeat){if(e.shiftKey)cancelTeamOrder();else beginPingHold(mouse.x+cam.x,mouse.y+cam.y)}else if(action==='ward'&&!e.repeat)placeWard(mouse.x+cam.x,mouse.y+cam.y);else if(action==='potion'&&!e.repeat)usePotion();else if(action==='attackMove'&&!e.repeat){attackCommandArmed=true;showToast('Укажите точку атаки')}else if(action==='awakening'&&!e.repeat)activateAwakening();else if(action==='target'&&!e.repeat)cycleHeroTarget(e.shiftKey?-1:1);else if(action==='sweeper'&&!e.repeat)useSweeper();else if(action==='controlWard'&&!e.repeat)placeControlWard(mouse.x+cam.x,mouse.y+cam.y);else if(action==='active'&&!e.repeat)useActiveItem();else if(action==='cycleItem'&&!e.repeat)cycleActiveItem();else if(action==='mastery'&&!e.repeat)useMasteryEmote()}
