function grantKill(t){if(t.plant){if(t.dead)return;if(t.plant==='vital'){consumeVitalPlant(t,hero);return}t.dead=true;t.hp=0;t.respawn=t.plant==='vital'?45:55;if(t.plant==='blast'){const a=Math.atan2(hero.y-t.y,hero.x-t.x),dist=270;hero.x=Math.max(80,Math.min(WORLD.w-80,hero.x+Math.cos(a)*dist));hero.y=Math.max(80,Math.min(WORLD.h-80,hero.y+Math.sin(a)*dist));hero.moveTarget=null;hero.attackMove=false;hero.homeguard=0;for(let i=0;i<22;i++)particles.push({x:t.x,y:t.y,a:Math.random()*6.28,life:.65,type:'dash'});floatText(hero.x,hero.y-42,'ВЗРЫВНОЙ ПРЫЖОК','#ffcf62');haptic([20,20,30])}else if(t.plant==='scry'){for(const u of [enemy,...botHeroes])if(u.team==='red'&&Math.hypot(u.x-t.x,u.y-t.y)<900)u.revealed=Math.max(u.revealed,8);for(const w of wards)if(w.team==='red'&&Math.hypot(w.x-t.x,w.y-t.y)<900)w.revealed=Math.max(w.revealed,8);particles.push({x:t.x,y:t.y,life:1.2,max:1.2,type:'wardPulse'});showToast('Око-цветок раскрыл область и вражеские тотемы')}return}if(t.rewarded)return;t.rewarded=true;if(t.structure==='inhibitor'){t.dead=true;t.respawn=60;inhibitorCollapse(t);hero.gold+=180;hero.xp+=110;stats.towers++;stats.goldEarned+=180;feed(hero.name+' разрушил ингибитор');announce('ИНГИБИТОР РАЗРУШЕН');checkHeroLevel();return}if(t.kind==='ward'){t.dead=true;t.hp=0;hero.gold+=15;stats.wards++;stats.goldEarned+=15;floatText(t.x,t.y-25,'ТОТЕМ +15','#ff9aaa');feed(hero.name+' уничтожил вражеский тотем');return}if(t.kind){if(t.kind==='shard'){hero.gold+=45;hero.xp+=35;stats.monsters++;stats.goldEarned+=45;t.dead=true;t.respawn=9999;t.rewarded=true;feed(hero.name+' разрушил Осколок Разлома');floatText(t.x,t.y-35,'ОСКОЛОК +45','#d8a0ff');checkHeroLevel();if(!monsters.some(m=>m.kind==='shard'&&!m.dead&&m.hp>0))announce('ЩИТ ТИТАНА РАЗРУШЕН');return}if(t.kind==='drake'){hero.gold+=140;hero.xp+=120;stats.monsters++;stats.goldEarned+=140;t.dead=true;t.respawn=65;t.rewarded=true;grantDragon('blue',t);grantTeamObjectiveGold(60,'Убит стихийный дракон');checkHeroLevel();return}const titan=t.kind==='titan',herald=t.kind==='herald',reward=titan?180:herald?120:65;hero.gold+=reward;hero.xp+=titan?160:herald?100:55;stats.monsters++;stats.goldEarned+=reward;if(rolePosition==='jungle'&&['stone','ember','wind'].includes(t.kind)){jungleState.clears++;jungleState.lastClear=time;jungleState.smiteUpgrades=Math.min(3,Math.floor(jungleState.clears/4));hero.hp=Math.min(hero.maxHp,hero.hp+Math.round(hero.maxHp*.035));hero.mana=Math.min(hero.maxMana,hero.mana+Math.round(hero.maxMana*.05));floatText(t.x,t.y-72,'ЛЕС + XP / HP / МАНА','#73e7b1');if(t.kind==='stone')jungleState.blueBuffs++;if(t.kind==='ember')jungleState.redBuffs++;if(t.kind==='wind')jungleState.routeIndex=(jungleState.routeIndex+1)%3;checkHeroLevel();}if(titan){teamBuff=60;for(const shard of monsters)if(shard.kind==='shard'){shard.dead=true;shard.respawn=9999}for(const b of botHeroes)if(b.team==='blue')b.hp=Math.min(b.maxHp,b.hp+55);if(gameMode==='raid')setTimeout(()=>endGame(true),700);else if(gameMode==='expedition')advanceExpedition();else if(gameMode==='runetrial'){}else setTimeout(()=>{if(running&&!gameOver)openTitanRelicChoice()},250)}else if(herald){siegeBuff=55;announce('ПОЛУЧЕНА СИЛА ОСАДЫ')}else buffs[t.kind]=35;feed(hero.name+' победил: '+t.name);sfx('kill');t.dead=true;t.respawn=titan?75:herald?90:22;checkHeroLevel();showToast(titan?'Команда получила силу Титана!':herald?'Сила осады: +30% урона сооружениям на 55 сек.':'Получено усиление: '+(t.kind==='stone'?'защита':t.kind==='ember'?'урон':'скорость'));return}if(t.maxHp===900){nexusCollapse(t,t.team==='red');return}const tower=isTower(t),isHero=t===enemy||t.isBot,isMinion=minions.includes(t),isSiege=isMinion&&t.siege,reward=tower?150:isHero?120+(t.bounty||0):isMinion?(t.goldReward??(isSiege?60:25)):gameMode==='aram'?35:25,xpReward=tower?80:isHero?90:isMinion?(t.xpReward??(isSiege?32:20)):gameMode==='aram'?45:30;hero.gold+=reward;hero.xp=Math.min(hero.xpNext,hero.xp+xpReward);stats.goldEarned+=reward;if(isMinion){stats.waveLastHits++;stats.waveGold+=reward;stats.waveXp+=xpReward;floatText(t.x,t.y-28,`+${reward} ◈`,'#ffd56d');if(xpReward>0)floatText(t.x,t.y-46,`+${xpReward} XP`,'#8fcfff');}if(tower){stats.towers++;feed(hero.name+' разрушил башню');sfx('kill');towerCollapse(t,'blue')}if(isHero){t.heroTag=0;if(t.bounty>0){announce('ПРЕРВАНА СЕРИЯ · +'+t.bounty+' ЗОЛОТА');floatText(t.x,t.y-55,'НАГРАДА +'+t.bounty,'#ffd36b')}t.bounty=0;t.deaths=(t.deaths||0)+1;stats.kills++;if(t===enemy){rivalPlayerVictory();recordDuelPoint('blue');recordDominionKill('blue')}chronoTakedown();stats.streak++;stats.bestStreak=Math.max(stats.bestStreak,stats.streak);const now=performance.now(),killChain=stats.firstBlood?(now-stats.lastKill<6500):false;let killCall='УБИЙСТВО';if(!stats.firstBlood){stats.firstBlood=true;killCall='ПЕРВАЯ КРОВЬ';announce('ПЕРВАЯ КРОВЬ')}else if(killChain){killCall=stats.streak>=5?'НЕУДЕРЖИМЫЙ':stats.streak>=3?'СЕРИЯ УБИЙСТВ':'ДВОЙНОЕ УБИЙСТВО';announce(killCall)}else if(stats.streak===3){killCall='СЕРИЯ УБИЙСТВ';announce(killCall)}else if(stats.streak===5){killCall='НЕУДЕРЖИМЫЙ';announce(killCall)}stats.lastKill=now;const burstColor=hero.color||'#63e6ff';for(let i=0;i<28;i++)particles.push({x:t.x,y:t.y,a:i*Math.PI/14,life:.75,max:.75,type:'killBurst',color:burstColor});floatText(t.x,t.y-62,killCall,'#fff0a6');combatImpact(Math.min(2,1.15+(stats.streak>=3?.18:0)));feed(hero.name+' уничтожил '+(t.name||'Разорителя'));sfx('kill')}if(isMinion)stats.minions++;if(isHero){t.dead=true;t.respawn=eliteRespawnTime();showToast('Вражеский герой повержен!')}checkHeroLevel();if(tower)showToast('Башня разрушена! +150 золота')}
function structureProtected(t){if(t.maxHp===900)return !inhibitors.some(i=>i.team===t.team&&(i.dead||i.hp<=0));if(t.structure==='inhibitor')return towers.some(s=>s.team===t.team&&s.hp>0&&Math.hypot(s.x-t.x,s.y-t.y)<720);return false}
function isTower(t){return !!t&&t.team&&Number.isFinite(t.tier)&&t.tier>=1&&t.tier<=2&&!t.structure}
function isStructure(t){return !!t&&(isTower(t)||t.maxHp===900||t.structure==='inhibitor')}
function structureTierLabel(t){if(!t)return '';if(t.structure==='inhibitor')return 'ИНГИБИТОР';if(t.maxHp===900)return 'ЯДРО';return t.tier===2?'ВНУТРЕННЯЯ БАШНЯ':'ВНЕШНЯЯ БАШНЯ'}
