function backdoorProtected(t,attackerTeam='blue'){return isStructure(t)&&!minions.some(m=>!m.dead&&m.team===attackerTeam&&Math.hypot(m.x-t.x,m.y-t.y)<320)}
function checkTowerPlates(t,oldHp,attackerTeam){if(!isTower(t)||t.tier!==1||time>=180||t.plates<=0)return;while(t.plates>0&&t.hp<=t.maxHp*t.plates/4&&oldHp>t.maxHp*t.plates/4){t.plates--;if(attackerTeam==='blue'){hero.gold+=45;stats.goldEarned+=45;stats.teamGold+=45;floatText(t.x,t.y-88,'ПЛАСТИНА +45','#ffd56d');feed('Разрушена пластина башни · +45 золота','blue')}else feed('Красные разрушили пластину башни','red')}}
function manualMovementActive(){return!!(touchMove.active||padInput.x||padInput.y||boundDown('moveRight')||boundDown('moveLeft')||boundDown('moveDown')||boundDown('moveUp'))}
function clearAttackBuffer(reason='clear'){if(!hero.attackBuffer)return false;if(reason==='expired')stats.expiredBufferedAttacks++;else if(reason==='movement')stats.movementCancelledBufferedAttacks++;else if(reason==='manual')stats.cancelledBufferedAttacks++;hero.attackBuffer=null;syncAttackBufferUi();return true}
function cancelBufferedInputs(){const skill=clearSkillBuffer('manual'),attack=clearAttackBuffer('manual');if(skill||attack){showToast(skill?'Подготовленная способность отменена':'Подготовленная атака отменена');haptic(8);return true}return false}
document.querySelector('#mobileBufferCancel')?.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();cancelBufferedInputs()})
function attackBlockedFeedback(message,preferred=null,reason=message){const token=`${preferred||'any'}:${reason}`,locks=attackBlockedFeedback.locks||(attackBlockedFeedback.locks={}),now=performance.now()*.001;if((locks[token]||0)>now)return false;locks[token]=now+.65;stats.blockedAttackFeedbacks++;showToast(`Атака: ${message}`);const selector=preferred==='hero'?'[data-skill="A"]':preferred==='minion'?'[data-skill="K"]':'[data-skill="A"],[data-skill="K"]';for(const button of document.querySelectorAll(selector))if(button.animate&&!reducedMotion)button.animate([{transform:'translateX(0)',filter:'brightness(1)'},{transform:'translateX(-3px)',filter:'brightness(1.45)'},{transform:'translateX(3px)'},{transform:'translateX(0)',filter:'brightness(1)'}],{duration:180,easing:'ease-out'});return true}
function requestAttack(preferred=null){if(!running||paused||hero.dead)return;if(hero.attackCd<=0&&hero.stun<=0){clearSkillBuffer('manual');clearAttackBuffer('manual');attack(preferred);return}if(hero.attackCd<=.2&&hero.stun<=.18){if(manualMovementActive()){attackBlockedFeedback('отпустите движение',preferred);return}clearSkillBuffer('manual');hero.attackBuffer={expires:time+.3,target:hero.target||null,preferred};stats.bufferedAttacks++;syncAttackBufferUi();return}const stun=Math.max(0,Number(hero.stun)||0),cd=Math.max(0,Number(hero.attackCd)||0),stunned=stun>=cd;attackBlockedFeedback(stunned?`оглушение ${stun.toFixed(1)}с`:`перезарядка ${cd.toFixed(1)}с`,preferred,stunned?'stun':'cooldown')}
function syncAttackBufferUi(){syncBufferCancelUi();const mode=hero.attackBuffer?.preferred|| (hero.attackBuffer?'any':'none');if(syncAttackBufferUi.last===mode)return;syncAttackBufferUi.last=mode;for(const b of document.querySelectorAll('[data-skill="A"],[data-skill="K"]')){const matches=mode==='any'||mode==='hero'&&b.dataset.skill==='A'||mode==='minion'&&b.dataset.skill==='K';const active=mode!=='none'&&matches;b.classList.toggle('buffered-attack',active);b.setAttribute('aria-pressed',String(active))}}
function updateAttackBuffer(){const queued=hero.attackBuffer;if(!queued){syncAttackBufferUi();return}if(typeof queued!=='object'||!Number.isFinite(queued.expires)||![null,undefined,'hero','minion'].includes(queued.preferred)||queued.expires>time+1||queued.target!=null&&typeof queued.target!=='object'){discardInvalidBuffer('attack');return}if(manualMovementActive()){clearAttackBuffer('movement');return}if(time>queued.expires||hero.dead){clearAttackBuffer('expired');return}if(hero.attackCd<=0&&hero.stun<=0){hero.attackBuffer=null;syncAttackBufferUi();stats.executedBufferedAttacks++;if(queued.target&&validTarget(queued.target,520))hero.target=queued.target;else if(queued.preferred){stats.bufferedAttackRetargets++;attackPreferred(queued.preferred);return}attack(queued.preferred)}}
function attack(preferred=null){if(!running||hero.attackCd>0||hero.dead||hero.stun>0)return;cancelRecall();hero.revealed=2.5;if(!validTarget(hero.target)){let near=null,best=Infinity;for(const t of [...minions,enemy,...botHeroes,...monsters,...plants,...wards,...towers]){if(!validTarget(t,310)||!hasLineOfSight(hero,t))continue;const d=Math.hypot(t.x-hero.x,t.y-hero.y),score=targetScore(t,d,310);if(score<best){best=score;near=t}}hero.target=near}if(!hero.target||hero.target.hp<=0){attackBlockedFeedback('нет цели рядом',preferred);return}if(structureProtected(hero.target)){hero.attackMove=false;attackBlockedFeedback('сначала разрушьте защитные сооружения',preferred);return}const d=hero.target,dist=Math.hypot(d.x-hero.x,d.y-hero.y);if(dist>310){hero.attackMove=true;showToast('Движение к цели');return}if(!hasLineOfSight(hero,d)){stats.wallOccludedAttacks=(stats.wallOccludedAttacks||0)+1;attackBlockedFeedback('цель закрыта стеной',preferred);return}hero.attackMove=true;hero.attackCd=.75/hero.attackSpeed;if(hero.kind==='forge')hero.forgeHeat=Math.min(100,hero.forgeHeat+(hero.forgeOverheat>0?4:9));hero.dir=Math.atan2(d.y-hero.y,d.x-hero.x);tutorialEvent('attack');haptic(14);const empowered=hero.kind==='phantom'&&hero.passiveTimer>=4;if(empowered){hero.passiveTimer=0;floatText(hero.x,hero.y-44,'ТЕНЕВОЙ УДАР','#c58aff')}if(hero.kind==='tempest'||hero.kind==='warden')hero.attackCounter++;const gravityProc=hero.kind==='warden'&&hero.attackCounter%(hero.awakening>0?2:3)===0;if(gravityProc)floatText(hero.x,hero.y-44,'ГРАВИМЕТКА','#65f0e8');const chain=hero.kind==='tempest'&&hero.attackCounter%(hero.awakening>0?2:3)===0;if(chain)floatText(hero.x,hero.y-44,'ЦЕПНАЯ МОЛНИЯ','#76ffd1');if(hero.items.has('blade'))hero.bladeCounter++;const bladeHits=hero.upgradedItems.has('blade')?3:4,bladeProc=hero.items.has('blade')&&hero.bladeCounter%bladeHits===0;if(bladeProc)floatText(hero.x,hero.y-60,'ШТОРМОВОЙ УДАР','#ffd56d');particles.push({x:hero.x,y:hero.y,tx:d.x,ty:d.y,life:.18,max:.18,type:'shot',target:d,empowered,chain,gravityProc,bladeProc,heroKind:hero.kind,color:hero.color})}
function inEnemyTowerRange(){return towers.some(t=>t.team==='red'&&t.hp>0&&Math.hypot(hero.x-t.x,hero.y-t.y)<300)}
function markForAssist(target){if(target===enemy||target.isBot)target.heroTag=5}
