function damageArea(x,y,r,dmg,type='magic'){type=normalizeDamageType(type);let hits=0;if(teamBuff>0)dmg*=1.2;for(const d of [...dummies,...minions,...towers,enemy,...nexuses,...monsters,...botHeroes,...inhibitors]){if(d.team==='blue'||d.dead||d.hp<=0||structureProtected(d))continue;if(d.hp>0&&Math.hypot(d.x-x,d.y-y)<=r+d.r){const oldHp=d.hp,actual=appliedDamage(d,outgoingDamage(d,dmg,type));if(actual<=0)continue;hits++;d.hp=Math.max(0,d.hp-actual);checkTowerPlates(d,oldHp,'blue');markForAssist(d);if((d===enemy||d.isBot)&&inEnemyTowerRange()){if(hero.towerAggro<=0)showToast('Башни переключились на вас!');hero.towerAggro=2.5;}stats.damage+=actual;recordDamageType('outgoing',type,actual);if(networkDuel.active&&d===enemy)netSend({type:'damage',amount:actual,damageType:type});if(hero.kind==='oracle')hero.mana=Math.min(hero.maxMana,hero.mana+4);if(dummies.includes(d))recordTrainingDamage(actual);const showDamageNumber=!compactWorldHud()||!minions.includes(d)||d===hero.target||d.hp<=0;if(showDamageNumber)floatText(d.x,d.y-25,'−'+Math.round(actual),type==='physical'?'#ff9a82':type==='true'?'#fff':'#b98cff');d.hit=.2;if(d.hp<=0){d.dead=!!d.team;grantKill(d);showToast('Цель уничтожена')}}}if(hits){sfx(hits>2?'kill':'hit');combatImpact(Math.min(1.6,.55+hits*.22))}}
