function spend(cost){if(keystone==='insight')cost=Math.ceil(cost*(hero.keystoneAscended?.72:.85));if(hero.mana<cost){showToast('Недостаточно энергии');return false}hero.mana-=cost;if(hero.items.has('core')&&hero.coreCd<=0&&hero.mana/hero.maxMana<=.3){hero.coreCd=35;const reserve=hero.upgradedItems.has('core')?45:30;hero.mana=Math.min(hero.maxMana,hero.mana+reserve);floatText(hero.x,hero.y-58,'ЭФИР +'+reserve,'#6db8ff');showToast('Эфирное ядро восстановило энергию')}return true}
