function smartAim(range=600){if(validTarget(hero.target,range))return Math.atan2(hero.target.y-hero.y,hero.target.x-hero.x);let target=null,best=Infinity;for(const u of [...dummies,...minions,enemy,...botHeroes,...monsters,...plants,...wards]){if(!validTarget(u,range))continue;const d=Math.hypot(u.x-hero.x,u.y-hero.y),score=targetScore(u,d,range);if(score<best){best=score;target=u}}if(target)hero.target=target;return target?Math.atan2(target.y-hero.y,target.x-hero.x):hero.dir}
function healBlueTeam(radius,amount){if(!Number.isFinite(radius)||radius<0||!Number.isFinite(amount)||amount<0){combatIntegrityTelemetry.invalidHealing++;return 0}let healPower=hero.healPower;if(!Number.isFinite(healPower)||healPower<0){combatIntegrityTelemetry.invalidHealing++;healPower=1}amount=Math.round(amount*healPower);if(hero.kind==='seraph'&&hero.awakening>0)amount=Math.round(amount*1.35);let total=0;const selfHeal=appliedHealing(hero,amount);if(selfHeal>0){total+=selfHeal;stats.healingDone+=selfHeal;floatText(hero.x,hero.y-38,'+'+Math.round(selfHeal),'#79f0a7')}for(const b of botHeroes)if(b.team==='blue'&&!b.dead&&Math.hypot(b.x-hero.x,b.y-hero.y)<radius){const healed=appliedHealing(b,amount);if(healed>0){total+=healed;stats.healingDone+=healed;floatText(b.x,b.y-34,'+'+Math.round(healed),'#79f0a7')}}return total}
