function syncBufferCancelUi(){const b=document.querySelector('#mobileBufferCancel'),skill=hero.skillBuffer?.key,attack=hero.attackBuffer?.preferred,active=!!(skill||attack);if(!b)return;b.classList.toggle('show',active);b.setAttribute('aria-hidden',String(!active));b.setAttribute('aria-label',skill?`Отменить подготовленную способность ${skill}`:attack?`Отменить подготовленную атаку ${attack==='hero'?'по герою':attack==='minion'?'по миньону':''}`:'Нет подготовленного действия');b.tabIndex=active?0:-1}
