function skillPreviewRange(key,kind=hero.kind,evolution=hero.evolution){if(key==='Q')return({guardian:90,phantom:105,oracle:175,tempest:210,seraph:150,archon:185,warden:145,forge:125,lumen:220}[kind]||160);if(key==='E'){const base=kind==='phantom'?390:kind==='tempest'?330:kind==='archon'?310:kind==='warden'?340:kind==='forge'?300:kind==='lumen'?325:250,evolved=evolution===kind+'_e'&&['guardian','phantom','warden','forge'].includes(kind);return base+(evolved?110:0)}if(key==='R')return({guardian:300,phantom:350,oracle:430,tempest:410,seraph:390,archon:370,warden:390,forge:365,lumen:420}[kind]||360);return 0}
function safeDashEndpoint(x,y,angle,distance,step=6){const valid=[x,y,angle,distance,step].every(Number.isFinite)&&distance>=0&&step>0;if(!valid){if(!safeDashEndpoint.invalidReported){stats.invalidDashInputs++;if(runtimeDiagnostics.invalidState.length<30)runtimeDiagnostics.invalidState.push({time:Date.now(),system:'safeDashEndpoint',reason:'invalid dash geometry'})}safeDashEndpoint.invalidReported=true;return{x:Number.isFinite(x)?x:hero.x,y:Number.isFinite(y)?y:hero.y,distance:0,blocked:true,invalid:true}}safeDashEndpoint.invalidReported=false;step=Math.max(1,Math.min(24,step));const margin=(Number.isFinite(hero.r)&&hero.r>0?Math.min(60,hero.r):22)+5;x=Math.max(margin,Math.min(WORLD.w-margin,x));y=Math.max(margin,Math.min(WORLD.h-margin,y));let safeX=x,safeY=y,travelled=0,blockedAt=null;for(let d=Math.min(step,distance);d<=distance;d=Math.min(distance,d+step)){const nx=x+Math.cos(angle)*d,ny=y+Math.sin(angle)*d;if(blocked(nx,ny)){blockedAt=d;break}safeX=nx;safeY=ny;travelled=d;if(d===distance)break}if(blockedAt!==null){let lo=travelled,hi=blockedAt;for(let i=0;i<6;i++){const mid=(lo+hi)/2,mx=x+Math.cos(angle)*mid,my=y+Math.sin(angle)*mid;if(blocked(mx,my))hi=mid;else lo=mid}travelled=lo;safeX=x+Math.cos(angle)*lo;safeY=y+Math.sin(angle)*lo}return{x:safeX,y:safeY,distance:travelled,blocked:blockedAt!==null}}
