function drawAttackBufferCue(){const queued=hero.attackBuffer;if(!queued||hero.dead)return;const left=Math.max(0,queued.expires-time),ratio=Math.min(1,left/.3),target=queued.target&&validTarget(queued.target,520)?queued.target:null,mode=queued.preferred==='hero'?'ГЕРОЙ':queued.preferred==='minion'?'МИНЬОН':'АТАКА';ctx.save();ctx.strokeStyle='#ff9a62';ctx.fillStyle='#ffd0ad';ctx.lineWidth=3;ctx.globalAlpha=.88;ctx.beginPath();ctx.arc(hero.x,hero.y,40,-Math.PI/2,-Math.PI/2+Math.PI*2*ratio);ctx.stroke();if(target){ctx.globalAlpha=.5;ctx.setLineDash([5,6]);ctx.beginPath();ctx.moveTo(hero.x,hero.y);ctx.lineTo(target.x,target.y);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(target.x,target.y,(target.r||24)+8,0,6.28);ctx.stroke()}ctx.font='900 9px system-ui';ctx.textAlign='center';ctx.fillText(mode,hero.x,hero.y-48);ctx.restore()}
