function playerRespawnTime(){return gameMode==='hunt'?6:gameMode==='tournament'?7:gameMode==='overlord'?10:gameMode==='escort'?7:(gameMode==='skirmish'||gameMode==='skirmishranked')?5:gameMode==='dominion'?6:gameMode==='aram'?Math.min(14,4+Math.floor(time/100)+Math.floor((hero.level-1)/4)):Math.min(22,5+Math.floor(time/90)*2+Math.floor((hero.level-1)/3))}
function botRespawnTime(){return gameMode==='hunt'?6:gameMode==='overlord'?6:gameMode==='escort'?7:(gameMode==='skirmish'||gameMode==='skirmishranked')?5:gameMode==='dominion'?6:gameMode==='aram'?Math.min(12,5+battleTier):Math.min(18,7+battleTier)}
function eliteRespawnTime(){return gameMode==='hunt'?6:gameMode==='overlord'?6:gameMode==='escort'?8:(gameMode==='skirmish'||gameMode==='skirmishranked')?6:gameMode==='dominion'?7:Math.min(20,8+battleTier)}
function applyHeroControl(kind,duration){if(!['stun','slow'].includes(kind)||!Number.isFinite(duration)||duration<0){combatIntegrityTelemetry.invalidStatuses++;return 0}if(duration===0)return 0;const repeated=Number.isFinite(hero.ccFatigue)&&hero.ccFatigue>0,tenacity=Number.isFinite(hero.tenacity)?Math.max(0,Math.min(.85,hero.tenacity)):0,final=Math.min(12,duration*(1-tenacity)*(repeated?.65:1));if(!applyUnitStatus(hero,kind,final))return 0;hero.ccFatigue=4;if(repeated)floatText(hero.x,hero.y-68,'УСТОЙЧИВОСТЬ','#9ff4d0');return final}
function hurtHero(amount,quiet=false,source='Противник',type='physical'){if(hero.dead)return 0;if(!Number.isFinite(amount)||amount<0){combatIntegrityTelemetry.invalidDamage++;return 0}type=normalizeDamageType(type);source=String(source||'Противник').slice(0,48);const defense=type==='physical'?hero.armor:type==='magic'?hero.resist:0,mitigation=type==='true'?1:100/(100+Math.max(-50,defense));let reduced=amount*directorPower('red')/directorPower('blue')*(stormBuffs.red>0?1.15:1)*(stormBuffs.blue>0?.88:1)*mitigation*(shrineBuffs.guard>0?.88:1)*(1/(1+dragonBuffs.blue.stone*.04+(dragonBuffs.blue.soul?.1:0)))*(hero.awakening>0?.8:1)*(hero.awakening>0&&hero.kind==='guardian' ? .8 : 1)*(hero.shield>0?.55:1)*(hero.kind==='guardian'&&hero.hp/hero.maxHp<.35?.8:1);if(hero.items.has('aegis')&&hero.aegisCd<=0&&hero.hp-reduced<=hero.maxHp*.3){hero.aegisCd=hero.upgradedItems.has('aegis')?38:45;hero.shield=Math.max(hero.shield,hero.upgradedItems.has('aegis')?3.2:2.5);reduced*=hero.upgradedItems.has('aegis') ? .48 : .55;floatText(hero.x,hero.y-58,'ЭГИДА','#8eeaff');showToast('Эгида активировала спасительный барьер')}const actual=appliedDamage(hero,reduced);hero.hp=Math.max(0,hero.hp-actual);stats.damageTaken+=actual;recordDamageType('incoming',type,actual);if(actual<=0)return 0;playerDamageFeedback(actual,type);if(actual>=1){hero.homeguard=0;hero.combatTimer=6;if(hero.awakening<=0)hero.aether=Math.min(100,hero.aether+Math.min(8,actual*.07));if(keystone==='resolve'&&hero.hp/hero.maxHp<=.5&&hero.runeCd<=0){hero.runeCd=hero.keystoneAscended?17:22;hero.shield=Math.max(hero.shield,hero.keystoneAscended?3.6:2.2);if(hero.keystoneAscended){const heal=hero.maxHp*.1;hero.hp=Math.min(hero.maxHp,hero.hp+heal);hero.slow=0;hero.stun=0;hero.ccFatigue=Math.max(hero.ccFatigue,5);floatText(hero.x,hero.y-78,'НЕСОКРУШИМАЯ ВОЛЯ +'+Math.round(heal),'#77e6ff')}else floatText(hero.x,hero.y-62,'РЕШИМОСТЬ','#77e6ff');showToast(hero.keystoneAscended?'Абсолютная решимость спасла героя':'Решимость создала защитный щит')}const now=performance.now(),last=hero.damageLog.at(-1);if(last&&last.source===source&&last.type===type&&now-last.time<900){last.amount+=actual;last.time=now}else hero.damageLog.push({source,amount:actual,type,time:now});hero.damageLog=hero.damageLog.slice(-5)}if(!quiet){if(hero.shield>0)floatText(hero.x,hero.y-40,'ЩИТ −'+Math.round(actual),'#72edff');else floatText(hero.x,hero.y-35,'−'+Math.round(actual),type==='magic'?'#c98cff':type==='true'?'#ffffff':'#ff7a86')}return actual}
function createDangerZone(x,y,r,delay,damage,source,effect='slow',color='#ff526c',affects='blue'){dangerZones.push({x,y,r,time:delay,max:delay,damage,source,effect,color,affects});particles.push({x,y,life:.35,max:.35,type:'enemyNova'})}
function updateDangerZones(dt){for(let i=dangerZones.length-1;i>=0;i--){const z=dangerZones[i];z.time-=dt;if(z.time>0)continue;if((z.affects==='blue'||z.affects==='all')&&!hero.dead&&Math.hypot(hero.x-z.x,hero.y-z.y)<z.r){hurtHero(z.damage,false,z.source,'magic');if(z.effect==='stun')applyHeroControl('stun',.75);else if(z.effect==='slow')applyHeroControl('slow',1.7)}else if(!hero.dead&&Math.hypot(hero.x-z.x,hero.y-z.y)<z.r+120){stats.dodges++;floatText(hero.x,hero.y-42,'УКЛОНЕНИЕ','#78efff')}for(const b of botHeroes)if((z.affects==='all'||b.team==='blue')&&!b.dead&&Math.hypot(b.x-z.x,b.y-z.y)<z.r){b.hp=Math.max(0,b.hp-z.damage);b[z.effect==='stun'?'stun':'slow']=Math.max(b[z.effect==='stun'?'stun':'slow']||0,z.effect==='stun'?.65:1.5);if(b.hp<=0){b.dead=true;b.respawn=botRespawnTime();b.deaths++}}if(z.affects==='all'&&!enemy.dead&&Math.hypot(enemy.x-z.x,enemy.y-z.y)<z.r){enemy.hp=Math.max(0,enemy.hp-z.damage);enemy.slow=Math.max(enemy.slow||0,1.5);if(enemy.hp<=0){enemy.dead=true;enemy.respawn=eliteRespawnTime();enemy.deaths++}}for(let p=0;p<24;p++)particles.push({x:z.x+(Math.random()-.5)*z.r,y:z.y+(Math.random()-.5)*z.r,life:.6,max:.6,type:'botBlast',color:z.color});shake=Math.max(shake,.22);dangerZones.splice(i,1)}}
function castRivalZone(enemyPower){enemy.zoneCd=enemy.archetype==='arcanist'?7:enemy.archetype==='hunter'?8:9;enemy.revealed=2.5;if(enemy.archetype==='bulwark'){createDangerZone(hero.x,hero.y,138,.85,enemy.damage*1.65*enemyPower,'Колосс · Сейсмический удар','stun','#ff9b62');enemy.state='СЕЙСМИЧЕСКИЙ УДАР'}else if(enemy.archetype==='arcanist'){for(let i=-1;i<=1;i++)createDangerZone(hero.x+i*82,hero.y+Math.abs(i)*28,70,.65+Math.abs(i)*.16,enemy.damage*1.35*enemyPower,'Морок · Каскад пустоты','slow','#c778ff');enemy.state='КАСКАД ПУСТОТЫ'}else if(enemy.archetype==='hunter'){const lead=85;createDangerZone(hero.x+Math.cos(hero.dir)*lead,hero.y+Math.sin(hero.dir)*lead,82,.62,enemy.damage*1.7*enemyPower,'Следопыт · Эфирная ловушка','slow','#ff6f9f');enemy.state='ЭФИРНАЯ ЛОВУШКА'}else{createDangerZone(hero.x+Math.cos(hero.dir)*35,hero.y+Math.sin(hero.dir)*35,105,1.05,enemy.damage*2.05*enemyPower,'Разоритель · Багровый метеор','stun','#ff4568');enemy.state='БАГРОВЫЙ МЕТЕОР'}showToast('Опасная способность: покиньте область!')}
function castRivalAbility(best,enemyPower){enemy.abilityCd=enemy.archetype==='hunter'?4.8:enemy.archetype==='arcanist'?5.2:6;enemy.revealed=2.5;if(enemy.archetype==='bulwark'){enemy.hp=Math.min(enemy.maxHp,enemy.hp+enemy.maxHp*.09);hurtHero(enemy.damage*1.25*enemyPower,false,'Колосс · Таран');applyHeroControl('stun',.55);floatText(enemy.x,enemy.y-48,'КАМЕННЫЙ ЩИТ','#ffbd78')}else if(enemy.archetype==='arcanist'){const a=Math.atan2(enemy.y-hero.y,enemy.x-hero.x);enemy.x+=Math.cos(a)*90;enemy.y+=Math.sin(a)*90;hurtHero(enemy.damage*1.65*enemyPower,false,'Морок · Разрыв','magic');hero.mana=Math.max(0,hero.mana-18);floatText(hero.x,hero.y-52,'−18 ЭНЕРГИИ','#c98cff')}else{enemy.x+=Math.cos(enemy.dir)*Math.min(enemy.archetype==='hunter'?165:120,best-70);enemy.y+=Math.sin(enemy.dir)*Math.min(enemy.archetype==='hunter'?165:120,best-70);hurtHero(enemy.damage*(enemy.archetype==='hunter'?1.55:1.8)*enemyPower,false,enemy.name+' · рывок');applyHeroControl('slow',enemy.archetype==='hunter'?1.2:1.8);floatText(hero.x,hero.y-52,'ЗАМЕДЛЕНИЕ','#7ddcff')}particles.push({x:enemy.x,y:enemy.y,life:.65,max:.65,type:'enemyNova'});showToast(enemy.name+' применил особую способность')}
function castRivalUltimate(enemyPower){rivalry.ultCd=24;enemy.revealed=4;enemy.state='ПРЕДЕЛ СОПЕРНИКА';announce(enemy.name+' · ПРЕДЕЛ СОПЕРНИКА');if(enemy.archetype==='bulwark'){enemy.hp=Math.min(enemy.maxHp,enemy.hp+enemy.maxHp*.18);hurtHero(enemy.damage*2.1*enemyPower,false,'Колосс · Несокрушимый предел','physical');applyHeroControl('stun',1.05);particles.push({x:enemy.x,y:enemy.y,life:1,max:1,type:'enemyNova'});floatText(enemy.x,enemy.y-62,'НЕСОКРУШИМЫЙ ПРЕДЕЛ','#ffd08a')}else if(enemy.archetype==='arcanist'){hero.mana=Math.max(0,hero.mana-35);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;createDangerZone(hero.x+Math.cos(a)*115,hero.y+Math.sin(a)*115,72,.55+i*.1,enemy.damage*1.35*enemyPower,'Морок · Венец бездны','slow','#c778ff')}floatText(hero.x,hero.y-62,'−35 ЭНЕРГИИ','#d89cff')}else if(enemy.archetype==='hunter'){const missing=1-hero.hp/hero.maxHp;enemy.x=hero.x-Math.cos(hero.dir)*75;enemy.y=hero.y-Math.sin(hero.dir)*75;hurtHero(enemy.damage*(1.8+missing)*enemyPower,false,'Следопыт · Последний след','physical');applyHeroControl('slow',2);for(let i=0;i<20;i++)particles.push({x:enemy.x,y:enemy.y,a:Math.random()*6.28,life:.5,type:'dash'})}else{for(let i=-1;i<=1;i++)createDangerZone(hero.x+i*95,hero.y+Math.abs(i)*45,88,.48+Math.abs(i)*.18,enemy.damage*1.6*enemyPower,'Разоритель · Тройной разлом','stun','#ff4568')}feed(enemy.name+' использовал высшую способность соперника','red');sfx('cast');shake=options.shake?.45:0}
function updateEnemy(dt){
 if(gameMode==='raid')return;
 if(enemy.dead){enemy.state='ВОЗРОЖДЕНИЕ';enemy.respawn-=dt;if(enemy.respawn<=0){enemy.dead=false;enemy.hp=enemy.maxHp;enemy.x=2180;enemy.y=400;enemy.rewarded=false;enemy.awakening=0;enemy.awakeningCd=Math.max(enemy.awakeningCd,22);enemy.state='ЛИНИЯ'}return}
 enemy.awakening=Math.max(0,enemy.awakening-dt);enemy.awakeningCd=Math.max(0,enemy.awakeningCd-dt);if(enemy.level>=8&&enemy.awakening<=0&&enemy.awakeningCd<=0&&enemy.hp/enemy.maxHp<.38){enemy.awakening=8;enemy.awakeningCd=60;enemy.hp=Math.min(enemy.maxHp,enemy.hp+enemy.maxHp*.12);enemy.abilityCd=Math.max(0,enemy.abilityCd-2);announce(enemy.name+' ПРОБУДИЛСЯ');particles.push({x:enemy.x,y:enemy.y,life:1,max:1,type:'enemyNova'})}const enemyHaste=(redShrineBuffs.haste>0?1.15:1)*(enemy.awakening>0?1.25:1);enemy.cd=Math.max(0,enemy.cd-dt*enemyHaste);enemy.zoneCd=Math.max(0,enemy.zoneCd-dt*enemyHaste);enemy.abilityCd=Math.max(0,enemy.abilityCd-dt*enemyHaste);rivalry.ultCd=Math.max(0,rivalry.ultCd-dt*enemyHaste);if(enemy.stun>0){enemy.state='ОГЛУШЁН';return}const enemyMoveSpeed=enemy.speed*(enemy.slow>0?.55:1)*(enemy.awakening>0?1.2:1),enemyPower=directorPower('red')*(stormBuffs.red>0?1.15:1)*(redTeamBuff>0?1.2:1)*(redShrineBuffs.power>0?1.12:1)*(enemy.awakening>0?1.2:1);if(aetherStorm.active&&Math.hypot(enemy.x-aetherStorm.x,enemy.y-aetherStorm.y)>aetherStorm.radius-70&&Math.hypot(enemy.x-2380,enemy.y-220)>190){const a=Math.atan2(aetherStorm.y-enemy.y,aetherStorm.x-enemy.x);enemy.state='БЕЖИТ ОТ БУРИ';enemy.x+=Math.cos(a)*enemyMoveSpeed*1.2*dt;enemy.y+=Math.sin(a)*enemyMoveSpeed*1.2*dt;return}
 const base={x:2180,y:400},hpRate=enemy.hp/enemy.maxHp,rivalRetreat=enemy.archetype==='bulwark'?.2:enemy.archetype==='hunter'?.32:.27;
 if(hpRate<rivalRetreat){enemy.state='ОТСТУПЛЕНИЕ';const a=Math.atan2(base.y-enemy.y,base.x-enemy.x);enemy.x+=Math.cos(a)*enemyMoveSpeed*1.15*dt;enemy.y+=Math.sin(a)*enemyMoveSpeed*1.15*dt;if(Math.hypot(base.x-enemy.x,base.y-enemy.y)<100){enemy.state='ЛЕЧЕНИЕ';enemy.hp=Math.min(enemy.maxHp,enemy.hp+35*dt)}return}
 let target=null,best=hero.dead||heroHiddenFromRed(enemy)?9999:Math.hypot(hero.x-enemy.x,hero.y-enemy.y);if(best<560)target=hero;
 for(const m of minions)if(!m.dead&&m.team==='blue'){const d=Math.hypot(m.x-enemy.x,m.y-enemy.y);if(d<best&&d<300){best=d;target=m}}
 if(target){enemy.state=target===hero?'АТАКА ГЕРОЯ':'ЗАЧИСТКА';enemy.dir=Math.atan2(target.y-enemy.y,target.x-enemy.x);
  if(target===hero&&rivalry.level>=3&&best<460&&rivalry.ultCd<=0)castRivalUltimate(enemyPower)
  else if(target===hero&&enemy.level>=4&&best<520&&enemy.zoneCd<=0)castRivalZone(enemyPower)
  else if(target===hero&&best<330&&enemy.abilityCd<=0)castRivalAbility(best,enemyPower)
  else if(best>125){enemy.x+=Math.cos(enemy.dir)*enemyMoveSpeed*dt;enemy.y+=Math.sin(enemy.dir)*enemyMoveSpeed*dt}else if(enemy.cd<=0){enemy.cd=.9;enemy.revealed=2.5;if(target===hero)hurtHero(enemy.damage*enemyPower,false,'Разоритель');else target.hp=Math.max(0,target.hp-enemy.damage*enemyPower);particles.push({x:enemy.x,y:enemy.y,tx:target.x,ty:target.y,life:.2,max:.2,type:'towerShot',target});if(target!==hero&&target.hp<=0)target.dead=true}
 }else{enemy.state='ЛИНИЯ';const patrol={x:1500,y:780},a=Math.atan2(patrol.y-enemy.y,patrol.x-enemy.x);if(Math.hypot(patrol.x-enemy.x,patrol.y-enemy.y)>80){enemy.x+=Math.cos(a)*enemyMoveSpeed*.55*dt;enemy.y+=Math.sin(a)*enemyMoveSpeed*.55*dt}}
 if(hero.hp<=0&&!hero.dead){hero.dead=true;hero.respawn=playerRespawnTime();enemy.kills++;enemy.bounty=Math.min(300,enemy.bounty+50);stats.deaths++;stats.streak=0;recordDuelPoint('red');recordDominionKill('red');rivalEnemyVictory();hero.gold=Math.max(0,hero.gold-80);feed(enemy.name+' уничтожил '+hero.name,'red');sfx('death');showToast('Возрождение через '+Math.ceil(hero.respawn)+' сек.')}
}
function botUltimateDamage(b,target,amount,type='magic'){if(!target||target.dead)return;if(b.awakening>0)amount*=1.2;if(target===hero){hurtHero(amount,false,b.name+' · ультимейт',type);if(hero.hp<=0&&!hero.dead){b.kills++;b.bounty=Math.min(300,b.bounty+50)}return}target.hp=Math.max(0,target.hp-amount);floatText(target.x,target.y-38,'−'+Math.round(amount),type==='magic'?'#d48cff':'#ff9a82');if(target.hp<=0){target.dead=true;target.respawn=target===enemy?eliteRespawnTime():botRespawnTime();target.deaths=(target.deaths||0)+1;target.bounty=0;b.kills++;b.bounty=Math.min(300,(b.bounty||0)+40);awardAssist(target);feed(b.name+' уничтожил '+(target.name||'Разорителя')+' ультимейтом',b.team)}}
function castBotSignature(b,target,dist){if(b.level<5||b.sigCd>0||!target||dist>360)return false;const enemyTeam=b.team==='blue'?'red':'blue';if(b.name==='БАСТИОН'||b.name==='ЖНЕЦ'){b.sigCd=16;const x=target.x,y=target.y;if(b.team==='red'&&target===hero)createDangerZone(x,y,120,.8,42*b.abilityPower,'Жнец · Разлом брони','stun','#ff526c');else{for(const u of [enemy,...botHeroes])if(!u.dead&&u.team===enemyTeam&&Math.hypot(u.x-x,u.y-y)<120){botUltimateDamage(b,u,42*b.abilityPower,'magic');u.stun=Math.max(u.stun||0,.7)}particles.push({x,y,life:.7,max:.7,type:'botBlast',color:b.color})}floatText(b.x,b.y-46,b.team==='blue'?'ЩИТ-ФРОНТ':'РАЗЛОМ БРОНИ',b.color);return true}if(b.name==='ИСКРА'||b.name==='ПЕПЕЛ'){b.sigCd=18;if(b.team==='red'&&target===hero){for(let i=-1;i<=1;i++)createDangerZone(hero.x+i*85,hero.y+Math.abs(i)*35,72,.65+Math.abs(i)*.18,30*b.abilityPower,'Пепел · Огненный каскад','slow','#ff784e')}else{const amount=58*b.abilityPower;botUltimateDamage(b,target,amount,'magic');particles.push({x:target.x,y:target.y,life:.8,max:.8,type:'botBlast',color:'#ffb05d'})}floatText(b.x,b.y-46,b.team==='blue'?'ЗВЁЗДНЫЙ ЗАЛП':'ОГНЕННЫЙ КАСКАД',b.color);return true}if(b.name==='СТРЕЛА'||b.name==='КОГОТЬ'){if((target.hp/target.maxHp)>.48)return false;b.sigCd=20;b.x=target.x-Math.cos(b.dir)*65;b.y=target.y-Math.sin(b.dir)*65;const amount=52*b.abilityPower;botUltimateDamage(b,target,amount,'physical');particles.push({x:b.x,y:b.y,a:Math.random()*6.28,life:.65,type:'dash'});floatText(target.x,target.y-48,'МЕТКА ОХОТЫ','#ff78c8');return true}if(b.name==='МУДРЕЦ'||b.name==='ВЕЩУН'){const allies=botHeroes.filter(a=>!a.dead&&a.team===b.team&&Math.hypot(a.x-b.x,a.y-b.y)<310),wounded=allies.some(a=>a.hp/a.maxHp<.62);if(!wounded)return false;b.sigCd=19;for(const a of allies){const heal=40*b.healPower;a.hp=Math.min(a.maxHp,a.hp+heal);floatText(a.x,a.y-36,'+'+Math.round(heal),'#72efa4')}if(b.team==='blue'&&!hero.dead&&Math.hypot(hero.x-b.x,hero.y-b.y)<310)hero.hp=Math.min(hero.maxHp,hero.hp+36*b.healPower);particles.push({x:b.x,y:b.y,life:1,max:1,type:'wardPulse'});floatText(b.x,b.y-48,b.team==='blue'?'КРУГ МУДРОСТИ':'БАГРОВОЕ СЛОВО',b.color);return true}return false}
function castBotUltimate(b,target){if(b.level<6||b.ultCd>0)return false;const coord=teamCombat[b.team],foes=b.team==='blue'?[enemy,...botHeroes.filter(x=>x.team==='red')]:[hero,...botHeroes.filter(x=>x.team==='blue')],allies=[...(b.team==='blue'?[hero]:[enemy]),...botHeroes.filter(x=>x.team===b.team)].filter(x=>x&&!x.dead);
 if(b.role==='ПОДДЕРЖКА'){const nearby=allies.filter(x=>Math.hypot(x.x-b.x,x.y-b.y)<330),weak=nearby.filter(x=>x.hp/x.maxHp<.68),critical=nearby.some(x=>x.hp/x.maxHp<.34);if(weak.length<2&&!critical)return false;if(coord.ultLock>0&&!critical)return false;b.ultCd=22;coord.ultLock=.8;for(const a of nearby){const heal=Math.round(a.maxHp*(a===hero?.16:.22));a.hp=Math.min(a.maxHp,a.hp+heal);floatText(a.x,a.y-40,'+'+heal,'#72efa4')}particles.push({x:b.x,y:b.y,life:.9,max:.9,type:'wardPulse'});floatText(b.x,b.y-58,critical?'ЭКСТРЕННОЕ ИСЦЕЛЕНИЕ':'ОБЩЕЕ ИСЦЕЛЕНИЕ','#72efa4');return true}
 if(coord.ultLock>0||!target||target.dead||Math.hypot(target.x-b.x,target.y-b.y)>330)return false;
 if(b.role==='ТАНК'){const nearbyFoes=foes.filter(x=>!x.dead&&Math.hypot(x.x-b.x,x.y-b.y)<145),nearbyAllies=allies.filter(x=>Math.hypot(x.x-b.x,x.y-b.y)<420);if(!nearbyFoes.length||nearbyAllies.length<2)return false;b.ultCd=20;coord.engage=3.2;coord.ultLock=.75;coord.target=target;feed((b.team==='blue'?'Синие':'Красные')+': ВХОДИМ · ИНИЦИАЦИЯ',b.team);particles.push({x:b.x,y:b.y,life:1.2,max:1.2,type:'ping',label:'ВХОД',color:b.team==='blue'?'#58ddff':'#ff6072'});for(const foe of nearbyFoes){botUltimateDamage(b,foe,38*b.abilityPower,'magic');if(foe===hero)applyHeroControl('stun',1.05);else foe.stun=Math.max(foe.stun||0,1.05)}particles.push({x:b.x,y:b.y,life:.75,max:.75,type:'enemyNova'});floatText(b.x,b.y-58,'ИНИЦИАЦИЯ · ГРАВИТАЦИОННЫЙ УДАР','#ffe36e');return true}
 if(b.role==='МАГ'){const cluster=foes.filter(x=>!x.dead&&Math.hypot(x.x-target.x,x.y-target.y)<175).length;if((coord.engage<=0&&cluster<2)||target.hp/target.maxHp<.22)return false;b.ultCd=18;coord.ultLock=.7;for(const foe of foes)if(!foe.dead&&Math.hypot(foe.x-target.x,foe.y-target.y)<175)botUltimateDamage(b,foe,55,'magic');particles.push({x:target.x,y:target.y,life:.8,max:.8,type:'botBlast',color:b.team==='blue'?'#72ddff':'#ff6685'});floatText(b.x,b.y-58,coord.engage>0?'КОМБО · ЭФИРНАЯ НОВА':'ЭФИРНАЯ НОВА','#d48cff');return true}
 if(b.role==='УБИЙЦА'&&target.hp/target.maxHp<.42){b.ultCd=21;coord.ultLock=.55;b.x=target.x-Math.cos(b.dir)*55;b.y=target.y-Math.sin(b.dir)*55;botUltimateDamage(b,target,42+target.maxHp*.18,'physical');for(let i=0;i<18;i++)particles.push({x:b.x,y:b.y,a:Math.random()*6.28,life:.45,type:'dash'});floatText(b.x,b.y-58,'КАЗНЬ ТЕНИ','#ff8ab7');return true}return false}
function issueTeamOrder(team,target,label,duration=16){const o=teamOrders[team];if(o.target===target&&o.time>4)return;o.target=target;o.time=duration;o.label=label;feed((team==='blue'?'Синие':'Красные')+': '+label,team);particles.push({x:target.x,y:target.y,life:1.4,max:1.4,type:'ping',label:'!',color:team==='blue'?'#58ddff':'#ff6072'})}
function teamKillsNow(team){return team==='blue'?stats.kills+botHeroes.filter(b=>b.team==='blue').reduce((n,b)=>n+(b.kills||0),0):(enemy.kills||0)+botHeroes.filter(b=>b.team==='red').reduce((n,b)=>n+(b.kills||0),0)}
