function updateShrines(dt){if(gameMode==='dominion'){updateDominion(dt);return}for(const k of Object.keys(shrineBuffs)){shrineBuffs[k]=Math.max(0,shrineBuffs[k]-dt);redShrineBuffs[k]=Math.max(0,redShrineBuffs[k]-dt)}for(const s of shrines){s.cooldown=Math.max(0,s.cooldown-dt);if(s.cooldown>0){s.progress=0;continue}const blueHere=(!hero.dead&&Math.hypot(hero.x-s.x,hero.y-s.y)<s.r+35)||botHeroes.some(b=>b.team==='blue'&&!b.dead&&Math.hypot(b.x-s.x,b.y-s.y)<s.r+30),redHere=(!enemy.dead&&Math.hypot(enemy.x-s.x,enemy.y-s.y)<s.r+35)||botHeroes.some(b=>b.team==='red'&&!b.dead&&Math.hypot(b.x-s.x,b.y-s.y)<s.r+30);if(blueHere!==redHere)s.progress=Math.max(-3,Math.min(3,s.progress+(blueHere?dt:-dt)));else s.progress+=(0-s.progress)*Math.min(1,dt*1.4);const winner=s.progress>=3?'blue':s.progress<=-3?'red':null;if(winner){s.progress=0;s.cooldown=75;s.owner=winner;(winner==='blue'?shrineBuffs:redShrineBuffs)[s.kind]=45;if(winner==='blue'){hero.gold+=90;stats.goldEarned+=90}announce((winner==='blue'?'СИНИЕ':'КРАСНЫЕ')+' ЗАХВАТИЛИ '+s.name);feed(`${winner==='blue'?hero.name:'Вражеская команда'} активировал ${s.name}${winner==='blue'?' · +90 золота':''}`,winner);showToast(winner==='blue'?(s.kind==='power'?'Сила алтаря: +12% урона':s.kind==='guard'?'Сила алтаря: −12% входящего урона':'Сила алтаря: +15% ускорения'):'Противник получил силу алтаря');for(let i=0;i<28;i++)particles.push({x:s.x,y:s.y,a:i*Math.PI/14,life:.8,type:winner==='blue'?'shield':'spark'});sfx(winner==='blue'?'win':'death')}}}
function drawTeleportTarget(){if(hero.teleportChannel<=0||!hero.teleportTarget)return;const t=hero.teleportTarget;ctx.strokeStyle='#c48cff';ctx.lineWidth=6;ctx.globalAlpha=.55+.35*Math.sin(time*9);ctx.beginPath();ctx.arc(t.x,t.y,55,0,6.28);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#e6ceff';ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.fillText('ТОЧКА ТЕЛЕПОРТА',t.x,t.y-64)}
