function drawSkirmishEvent(){if(!(gameMode==='skirmish'||gameMode==='skirmishranked')||!skirmish.event)return;const def=skirmishEvents[skirmish.event],radius=skirmish.event==='well'?235:skirmish.event==='storm'?610:330;ctx.save();ctx.strokeStyle=def.color;ctx.fillStyle=def.color+'18';ctx.lineWidth=7;ctx.globalAlpha=.7+.25*Math.sin(time*5);ctx.beginPath();ctx.arc(1320,900,radius,0,6.28);ctx.fill();ctx.stroke();if(skirmish.event==='storm'){ctx.setLineDash([18,14]);ctx.lineWidth=12;ctx.beginPath();ctx.arc(1320,900,radius,0,6.28);ctx.stroke();ctx.setLineDash([])}ctx.globalAlpha=1;ctx.fillStyle=def.color;ctx.font='900 13px system-ui';ctx.textAlign='center';ctx.fillText(def.name+' · '+Math.ceil(skirmish.eventTimer)+'с',1320,900-radius-18);ctx.restore()}
function drawHunt(){if(gameMode!=='hunt')return;for(const [team,bank] of Object.entries(hunt.banks)){ctx.fillStyle=team==='blue'?'#43dfff22':'#ff607522';ctx.strokeStyle=team==='blue'?'#63eaff':'#ff7184';ctx.lineWidth=6;ctx.beginPath();ctx.arc(bank.x,bank.y,82,0,6.28);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font='900 11px system-ui';ctx.textAlign='center';ctx.fillText('ХРАНИЛИЩЕ',bank.x,bank.y+4);const raid=team==='blue'?hunt.raidRed:hunt.raidBlue,lock=team==='blue'?hunt.raidLockBlue:hunt.raidLockRed;if(raid>0){ctx.strokeStyle='#ffd460';ctx.lineWidth=8;ctx.beginPath();ctx.arc(bank.x,bank.y,94,-Math.PI/2,-Math.PI/2+Math.PI*2*raid/4);ctx.stroke()}if(lock>0){ctx.fillStyle='#ffd460';ctx.fillText(`ЗАЩИТА ${Math.ceil(lock)}с`,bank.x,bank.y+24)}}for(const p of hunt.pickups){if(!p.active)continue;const pulse=1+Math.sin(time*5+p.x)*.15;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(time*1.4);ctx.scale(pulse,pulse);ctx.fillStyle=p.value===2?'#ffd86b':'#7ceaff';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=20;ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(12,0);ctx.lineTo(0,16);ctx.lineTo(-12,0);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,0,4,0,6.28);ctx.fill();ctx.restore();if(p.value===2){ctx.fillStyle='#ffe99b';ctx.font='900 10px system-ui';ctx.textAlign='center';ctx.fillText('×2',p.x,p.y-22)}}for(const u of [hero,enemy,...botHeroes])if(!u.dead&&(u.huntCarry||0)>0){ctx.fillStyle=u.team==='blue'?'#73eaff':'#ff7687';ctx.font='900 12px system-ui';ctx.textAlign='center';ctx.fillText(`✦ ${u.huntCarry}`,u.x,u.y-48)} }
function drawEscort(){if(gameMode!=='escort')return;ctx.save();ctx.strokeStyle='#79e9ff55';ctx.lineWidth=12;ctx.setLineDash([18,14]);ctx.beginPath();escort.path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.setLineDash([]);ctx.translate(escort.x,escort.y);ctx.rotate(time*.8);ctx.fillStyle='#0b2934';ctx.strokeStyle=escort.contested?'#ff6576':'#79e9ff';ctx.lineWidth=6;ctx.beginPath();for(let i=0;i<6;i++){const a=i*Math.PI/3,x=Math.cos(a)*32,y=Math.sin(a)*32;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill();ctx.stroke();ctx.rotate(-time*1.6);ctx.fillStyle='#ffd66b';ctx.beginPath();ctx.arc(0,0,11,0,6.28);ctx.fill();escort.modules.forEach((id,i)=>{const a=i*Math.PI+time,color=id==='engine'?'#ffd66b':id==='aegis'?'#6ee9ff':id==='medbay'?'#67efa8':id==='disruptor'?'#d081ff':'#ffffff';ctx.fillStyle=color;ctx.beginPath();ctx.arc(Math.cos(a)*46,Math.sin(a)*46,6,0,6.28);ctx.fill()});ctx.restore();ctx.fillStyle='#e8fbff';ctx.font='900 11px system-ui';ctx.textAlign='center';ctx.fillText(escort.contested?'ОСПАРИВАЕТСЯ':'ЭФИРНОЕ ЯДРО',escort.x,escort.y-48);bar(escort.x,escort.y-40,90,7,escort.progress,escort.contested?'#ff6576':'#63e7ff')}
function drawShrines(){for(const s of shrines){ctx.save();ctx.translate(s.x,s.y);if(gameMode==='dominion'&&shrines[dominion.crownIndex]===s){ctx.strokeStyle='#ffd76b';ctx.lineWidth=4;ctx.globalAlpha=.65+.3*Math.sin(time*5);ctx.beginPath();ctx.arc(0,0,s.r+20,0,6.28);ctx.stroke();ctx.fillStyle='#ffd76b';ctx.font='900 14px system-ui';ctx.textAlign='center';ctx.fillText('♛',0,-s.r-23);ctx.globalAlpha=1}ctx.globalAlpha=s.cooldown>0?.38:1;ctx.strokeStyle=s.color;ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,s.r,0,6.28);ctx.stroke();ctx.fillStyle='#09171dcc';ctx.beginPath();ctx.arc(0,0,s.r-6,0,6.28);ctx.fill();if(gameMode==='dominion'){ctx.fillStyle=s.owner==='blue'?'#245d75aa':s.owner==='red'?'#742d3baa':'#18262acc';ctx.beginPath();ctx.arc(0,0,s.r-8,0,6.28);ctx.fill();ctx.strokeStyle=(s.domProgress||0)>=0?'#59ddff':'#ff6476';ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,0,s.r+10,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.min(1,Math.abs(s.domProgress||0)/100));ctx.stroke()}ctx.fillStyle=s.color;ctx.font='900 25px system-ui';ctx.textAlign='center';ctx.fillText(s.kind==='power'?'⚔':s.kind==='guard'?'⬡':'◷',0,9);ctx.globalAlpha=1;if(Math.abs(s.progress)>.02){ctx.strokeStyle=s.progress>0?'#59ddff':'#ff6476';ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,0,s.r+9,-Math.PI/2,-Math.PI/2+Math.PI*2*Math.abs(s.progress)/3);ctx.stroke()}ctx.fillStyle=s.cooldown>0?(s.owner==='red'?'#ff7180':'#75dfff'):'#d9edf1';ctx.font='800 9px system-ui';ctx.fillText(gameMode==='dominion'?(s.owner==='blue'?'СИНИЕ · ':s.owner==='red'?'КРАСНЫЕ · ':'НЕЙТРАЛЬ · ')+s.name:s.cooldown>0?(s.owner==='red'?'КРАСНЫЕ ':'СИНИЕ ')+Math.ceil(s.cooldown)+'с':s.name,0,s.r+20);if(gameMode==='dominion'&&s.owner){ctx.fillStyle='#ffd66b';ctx.fillText(`ИМПУЛЬС ${Math.ceil(s.pulseCd||0)}с`,0,s.r+33)}ctx.restore()}}
function spawnTitanShards(titan,phase){const count=phase===3?3:2;for(let i=0;i<count;i++){const a=i*Math.PI*2/count+phase*.7,x=titan.x+Math.cos(a)*175,y=titan.y+Math.sin(a)*175;monsters.push({x,y,homeX:x,homeY:y,r:18,hp:120+phase*45,maxHp:120+phase*45,damage:8+phase*3,kind:'shard',name:'ОСКОЛОК РАЗЛОМА',cd:0,dead:false,respawn:0,rewarded:false})}announce(phase===3?'ТИТАН ПРИЗВАЛ ЯДРО РАЗЛОМА':'ТИТАН ПРИЗВАЛ ОСКОЛКИ');showToast('Осколки защищают Титана — уничтожьте их!')}
function updateJungle(dt){updateJungleCamps(dt);updateJungleRoleSystem(dt);teamBuff=Math.max(0,teamBuff-dt);redTeamBuff=Math.max(0,redTeamBuff-dt);siegeBuff=Math.max(0,siegeBuff-dt);redSiegeBuff=Math.max(0,redSiegeBuff-dt);for(const k of Object.keys(buffs))buffs[k]=Math.max(0,buffs[k]-dt);for(const m of monsters){if(m.dead){m.respawn-=dt;if(m.respawn<=0){m.dead=false;m.hp=m.maxHp;m.x=m.homeX;m.y=m.homeY;m.rewarded=false;if(m.kind==='titan'){m.phase=1;m.slamCd=5;m.slamTimer=0;m.shardPhase=1;for(const shard of monsters)if(shard.kind==='shard'){shard.dead=true;shard.respawn=9999}}if(m.kind==='drake'){const order=['ember','stone','wind'],names={ember:'ПЛАМЕННЫЙ ДРАКОН',stone:'КАМЕННЫЙ ДРАКОН',wind:'ШТОРМОВОЙ ДРАКОН'};m.element=order[(order.indexOf(m.element)+1)%3];m.name=names[m.element];m.maxHp+=55;m.hp=m.maxHp;m.damage+=2;announce(m.name+' ВОЗРОДИЛСЯ')}}continue}m.cd=Math.max(0,m.cd-dt);if(m.kind==='titan'){const previousPhase=m.phase;m.phase=m.hp/m.maxHp<=.3?3:m.hp/m.maxHp<=.65?2:1;if(m.phase>previousPhase){announce(m.phase===3?'ТИТАН В ЯРОСТИ':'ТИТАН ПРОБУЖДАЕТСЯ');feed(`Титан Разлома перешёл в фазу ${m.phase}`);shake=Math.max(shake,.35);if(m.phase>m.shardPhase){m.shardPhase=m.phase;spawnTitanShards(m,m.phase)}}m.slamCd=Math.max(0,m.slamCd-dt);if(m.slamTimer>0){m.slamTimer-=dt;if(m.slamTimer<=0){const slamDamage=50+m.phase*18;if(!hero.dead&&Math.hypot(hero.x-m.slamX,hero.y-m.slamY)<155){hurtHero(slamDamage,false,'Удар Титана','magic');applyHeroControl('slow',1.4)}for(const b of botHeroes)if(!b.dead&&Math.hypot(b.x-m.slamX,b.y-m.slamY)<155){b.hp-=slamDamage;if(b.hp<=0){b.dead=true;b.respawn=botRespawnTime();b.deaths++}}particles.push({x:m.slamX,y:m.slamY,life:.8,max:.8,type:'enemyNova'});shake=Math.max(shake,.45);haptic([30,20,40])}}if(gameMode==='expedition'){m.specialCd=Math.max(0,(m.specialCd||0)-dt);if(m.specialCd<=0&&!hero.dead){const stage=m.expeditionStage||expedition.stage;m.specialCd=stage===1?9:stage===2?7:6;if(stage===1){const a=Math.atan2(hero.y-m.y,hero.x-m.x);m.x+=Math.cos(a)*120;m.y+=Math.sin(a)*120;createDangerZone(hero.x,hero.y,105,.7,m.damage*1.4,'Страж Врат · Таран','stun','#69dfff')}else if(stage===2){for(let i=0;i<4;i++){const a=i*Math.PI/2+time;createDangerZone(hero.x+Math.cos(a)*125,hero.y+Math.sin(a)*125,68,.55+i*.12,m.damage*1.15,'Пожиратель · Грозовой круг','slow','#c778ff')}}else{const aliveShards=monsters.filter(x=>x.kind==='shard'&&!x.dead&&x.hp>0).length;if(aliveShards)m.hp=Math.min(m.maxHp,m.hp+m.maxHp*.04*aliveShards);for(let i=0;i<3;i++){const a=i*Math.PI*2/3;createDangerZone(hero.x+Math.cos(a)*95,hero.y+Math.sin(a)*95,78,.65+i*.12,m.damage*1.25,'Владыка · Разлом реальности','stun','#ff6078')}}announce(m.name+' · ОСОБАЯ МЕХАНИКА')}}}let target=!hero.dead&&Math.hypot(hero.x-m.x,hero.y-m.y)<260?hero:null,best=target?Math.hypot(hero.x-m.x,hero.y-m.y):260;for(const b of botHeroes)if(!b.dead){const d=Math.hypot(b.x-m.x,b.y-m.y);if(d<best){best=d;target=b}}if(m.kind==='titan'&&target&&m.slamCd<=0&&m.slamTimer<=0){m.slamTimer=1.25;m.slamCd=m.phase===3?5.5:m.phase===2?7:9;m.slamX=target.x;m.slamY=target.y;if(target===hero)showToast('Титан готовит удар — покиньте область!')}if(target){const a=Math.atan2(target.y-m.y,target.x-m.x);if(best>70){const ms=m.kind==='titan'?(m.phase===3?118:m.phase===2?98:82):82;m.x+=Math.cos(a)*ms*dt;m.y+=Math.sin(a)*ms*dt}else if(m.cd<=0){m.cd=1.25;const titanPower=m.kind==='titan'?(m.phase===3?1.55:m.phase===2?1.25:1):1;if(target===hero){const armor=buffs.stone>0?.6:1;hurtHero(m.damage*armor*titanPower,false,m.name)}else{target.hp-=m.damage*titanPower;if(target.hp<=0){target.dead=true;target.respawn=botRespawnTime();target.deaths++}}particles.push({x:m.x,y:m.y,tx:target.x,ty:target.y,life:.18,max:.18,type:'minionShot',target})}}else{const a=Math.atan2(m.homeY-m.y,m.homeX-m.x);m.x+=Math.cos(a)*45*dt;m.y+=Math.sin(a)*45*dt}}}
function escalateBattle(){battleTier++;nextEscalation+=escalationInterval;enemy.maxHp+=35;enemy.hp+=35;enemy.damage+=3;for(const b of botHeroes){b.maxHp+=22;b.hp+=22;b.damage+=3}announce('ЭСКАЛАЦИЯ · ФАЗА '+battleTier);feed('Миньоны и герои стали сильнее');sfx('kill')}
function spawnRiverRune(){const spots=[[1135,735],[1465,1065]],spot=spots[riverRune.cycle%2],types=Object.keys(riverRuneTypes);riverRune.x=spot[0];riverRune.y=spot[1];riverRune.type=types[Math.floor(Math.random()*types.length)];riverRune.active=true;riverRune.life=45;riverRune.cycle++;announce(riverRuneTypes[riverRune.type].name+' ПОЯВИЛАСЬ В РЕКЕ');feed('В реке появилась '+riverRuneTypes[riverRune.type].name.toLowerCase());rally.x=riverRune.x;rally.y=riverRune.y;rally.time=teamStrategy==='objective'?24:14;rally.type='attack';rally.target=null;rally.label='РЕЧНАЯ РУНА';rally.color=riverRuneTypes[riverRune.type].color;sfx('cast');particles.push({x:riverRune.x,y:riverRune.y,life:1.5,max:1.5,type:'ping',color:rally.color,label:'◆'})}
function collectRiverRune(team){const data=riverRuneTypes[riverRune.type];riverRune.active=false;riverRune.next=120;if(team==='blue'){stats.riverRunes++;if(riverRune.type==='wealth'){hero.gold+=180;stats.goldEarned+=180}if(riverRune.type==='renewal'){hero.hp=Math.min(hero.maxHp,hero.hp+hero.maxHp*.45);hero.mana=Math.min(hero.maxMana,hero.mana+hero.maxMana*.5)}if(riverRune.type==='surge')hero.itemSprint=Math.max(hero.itemSprint,14);if(riverRune.type==='wisdom'){hero.xp+=120;checkHeroLevel()}hero.aether=Math.min(100,hero.aether+20);floatText(hero.x,hero.y-55,data.name,data.color);haptic([18,20,25])}else redTeamBuff=Math.max(redTeamBuff,12);announce('ПРОТИВНИК ЗАБРАЛ '+data.name);feed('Красная команда получила речную руну','red')}
function updateRiverRune(dt){if(gameMode==='aram'||gameMode==='raid'||gameMode==='dominion'||gameMode==='escort'||gameMode==='overlord'||gameMode==='tournament'||gameMode==='hunt'||(gameMode==='skirmish'||gameMode==='skirmishranked')||(gameMode==='duel'||gameMode==='duelranked')||gameMode==='expedition')return;if(!riverRune.active){riverRune.next-=dt;if(riverRune.next<=0)spawnRiverRune();return}riverRune.life-=dt;if(riverRune.life<=0){riverRune.active=false;riverRune.next=75;return}if(!hero.dead&&Math.hypot(hero.x-riverRune.x,hero.y-riverRune.y)<55){collectRiverRune('blue');return}for(const b of botHeroes)if(!b.dead&&b.hp>0&&Math.hypot(b.x-riverRune.x,b.y-riverRune.y)<50){collectRiverRune(b.team);return}}
function drawRiverRune(){if(!riverRune.active)return;const data=riverRuneTypes[riverRune.type],pulse=1+Math.sin(time*6)*.12;ctx.save();ctx.translate(riverRune.x,riverRune.y);ctx.shadowColor=data.color;ctx.shadowBlur=22;ctx.strokeStyle=data.color;ctx.fillStyle=data.color+'55';ctx.lineWidth=5;ctx.rotate(time*.7);ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,r=(i%2?18:30)*pulse,x=Math.cos(a)*r,y=Math.sin(a)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill();ctx.stroke();ctx.rotate(-time*1.4);ctx.beginPath();ctx.arc(0,0,11,0,6.28);ctx.stroke();ctx.restore()}
function updateChaos(dt){if(matchMutator!=='chaos')return;chaosTimer-=dt;if(chaosTimer>0)return;chaosTimer=38+Math.random()*18;stats.chaosEvents++;const event=Math.floor(Math.random()*5);if(event===0){for(const u of [hero,enemy,...botHeroes])if(!u.dead){u.hp=Math.min(u.maxHp,u.hp+u.maxHp*.3);if(u.maxMana)u.mana=Math.min(u.maxMana,u.mana+u.maxMana*.4)}announce('ХАОС: ВОЛНА ВОССТАНОВЛЕНИЯ')}else if(event===1){siegeBuff=Math.max(siegeBuff,25);redSiegeBuff=Math.max(redSiegeBuff,25);announce('ХАОС: ДВОЙНАЯ ОСАДА')}else if(event===2){stormBuffs.blue=Math.max(stormBuffs.blue,18);stormBuffs.red=Math.max(stormBuffs.red,18);announce('ХАОС: ОБЕ КОМАНДЫ ПЕРЕГРУЖЕНЫ')}else if(event===3){for(const k of ['Q','W','E','R'])hero.cd[k]=0;for(const b of botHeroes){b.sigCd=0;b.ultCd=0}enemy.cd=0;enemy.abilityCd=0;enemy.zoneCd=0;announce('ХАОС: ПЕРЕЗАРЯДКА СБРОШЕНА')}else{if(!riverRune.active)spawnRiverRune();riverRune.life=Math.max(riverRune.life,60);announce('ХАОС: УСИЛЕННАЯ РЕЧНАЯ РУНА')}sfx('cast');shake=options.shake?.35:0}
function rivalEnemyVictory(){rivalry.enemyStreak++;rivalry.playerStreak=0;const targetLevel=rivalry.enemyStreak>=6?3:rivalry.enemyStreak>=4?2:rivalry.enemyStreak>=2?1:0;if(targetLevel>rivalry.level){rivalry.level=targetLevel;rivalry.bonusDamage+=3;rivalry.bonusHp+=18;enemy.damage+=3;enemy.maxHp+=18;enemy.hp=Math.min(enemy.maxHp,enemy.hp+18);enemy.bounty=(enemy.bounty||0)+60;announce(`ЗАКЛЯТЫЙ СОПЕРНИК · УРОВЕНЬ ${rivalry.level}`);feed(`Разоритель усилился после серии побед · награда ${enemy.bounty} золота`,'red')}}
function rivalPlayerVictory(){rivalry.playerStreak++;profile.rivalWins[enemy.archetype]=(profile.rivalWins[enemy.archetype]||0)+1;rivalry.enemyStreak=0;if(rivalry.level>0){stats.rivalDefeats++;rivalry.defeats++;announce('ЗАКЛЯТЫЙ СОПЕРНИК ПОВЕРЖЕН');feed('Сила соперника ослабла','blue');const removeDamage=Math.min(3,rivalry.bonusDamage),removeHp=Math.min(18,rivalry.bonusHp);rivalry.bonusDamage-=removeDamage;rivalry.bonusHp-=removeHp;enemy.damage=Math.max(1,enemy.damage-removeDamage);enemy.maxHp=Math.max(80,enemy.maxHp-removeHp);enemy.hp=Math.min(enemy.hp,enemy.maxHp);rivalry.level=Math.max(0,rivalry.level-1)}}
const fortificationDefs=[
 {id:'arsenal',name:'Эфирный арсенал',desc:'Герой и союзники получают +10% к урону.',apply:()=>{hero.damage*=1.1;for(const b of botHeroes.filter(b=>b.team==='blue'))b.damage*=1.1}},
 {id:'bulwark',name:'Обшивка ядра',desc:'Максимальное здоровье ядра +18%, восстановление 25%.',apply:()=>{const c=nexuses.find(n=>n.team==='blue');if(c){c.maxHp=Math.round(c.maxHp*1.18);c.hp=Math.min(c.maxHp,c.hp+c.maxHp*.25)}}},
 {id:'medbay',name:'Полевой лазарет',desc:'Максимальное здоровье команды +8% и полное лечение.',apply:()=>{for(const u of [hero,...botHeroes.filter(b=>b.team==='blue')]){u.maxHp=Math.round(u.maxHp*1.08);u.hp=u.maxHp}}},
 {id:'turrets',name:'Перегрузка башен',desc:'Союзные башни получают +25% урона.',apply:()=>{for(const t of towers.filter(t=>t.team==='blue'))t.damage=(t.damage||28)*1.25}},
 {id:'treasury',name:'Военный резерв',desc:'Немедленно получить 750 золота и 300 очков.',apply:()=>{hero.gold+=750;survival.score+=300}},
 {id:'barrier',name:'Рунный барьер',desc:'Команда получает щит в 20% максимального здоровья.',apply:()=>{for(const u of [hero,...botHeroes.filter(b=>b.team==='blue')])u.shield=(u.shield||0)+u.maxHp*.2}}
];
function openFortificationChoice(){if((gameMode!=='survival'&&gameMode!=='endless')||gameOver)return;const panel=document.querySelector('#fortificationMenu'),box=document.querySelector('#fortificationChoices');if(!talentMenu.classList.contains('hidden')){setTimeout(openFortificationChoice,400);return}paused=true;releaseWakeLock();document.querySelector('#fortificationWave').textContent=`Волна ${survival.cleared} отражена · выберите одно постоянное усиление`;box.innerHTML='';const choices=[...fortificationDefs].sort(()=>Math.random()-.5).slice(0,3);for(const upgrade of choices){const level=survival.fortifications[upgrade.id]||0,button=document.createElement('button');button.innerHTML=`<em>УРОВЕНЬ ${level+1}</em><strong>${upgrade.name}</strong><small>${upgrade.desc}</small>`;button.onclick=()=>{upgrade.apply();survival.fortifications[upgrade.id]=level+1;survival.drafts++;panel.classList.add('hidden');paused=false;last=performance.now();requestWakeLock();announce('БАСТИОН: '+upgrade.name);feed(`Усиление ${upgrade.name} · уровень ${level+1}`,'blue');requestAnimationFrame(loop)};box.appendChild(button)}const levels=document.createElement('div');levels.className='fortification-levels';levels.textContent=`Выбрано усилений: ${survival.drafts} · следующий элитный штурм: ${gameMode==='endless'?Math.ceil((survival.cleared+1)/5)*5:Math.min(15,Math.ceil((survival.cleared+1)/5)*5)} волна`;box.appendChild(levels);panel.classList.remove('hidden');box.querySelector('button')?.focus()}
function updateSurvivalBosses(dt){if((gameMode!=='survival'&&gameMode!=='endless'))return;for(const b of minions.filter(m=>m.survivalBoss)){if(b.dead||b.hp<=0){if(!b.bossCounted){b.bossCounted=true;survival.bossKills++;survival.score+=750;const bossGold=Math.round(350*(1+(profile.bastionTech.bounty||0)*.05));hero.gold+=bossGold;announce('КОМАНДИР ШТУРМА ПОВЕРЖЕН');feed(`${b.bossName} уничтожен · +${bossGold} золота`,'blue')}continue}b.abilityCd=Math.max(0,(b.abilityCd||0)-dt);if(b.abilityCd>0)continue;if(b.bossType==='ram'){for(const m of minions.filter(m=>m.team==='red'&&!m.dead&&Math.hypot(m.x-b.x,m.y-b.y)<260)){m.hp=Math.min(m.maxHp,m.hp+m.maxHp*.08);m.damage*=1.025}particles.push({x:b.x,y:b.y,life:.8,max:.8,type:'nova'});feed('Таранщик укрепляет легион','red');b.abilityCd=7}else if(b.bossType==='hexer'){const targets=[hero,...botHeroes.filter(x=>x.team==='blue'&&!x.dead)];const target=targets.sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0];if(target)createDangerZone(target.x,target.y,105,1.15,52+wave*2,'Пепельное клеймо','slow','#ff713c');b.abilityCd=5.5}else{const core=nexuses.find(n=>n.team==='blue');if(core&&!core.dead){core.hp=Math.max(1,core.hp-core.maxHp*.025);survival.perfect=false;particles.push({x:core.x,y:core.y,life:1,max:1,type:'nova'});feed('Колосс обстреливает ядро издали','red')}b.abilityCd=7}}}
function updateSurvival(dt){if((gameMode!=='survival'&&gameMode!=='endless')||survival.finished)return;updateSurvivalBosses(dt);if(siegeDifficulty!=='normal'){survival.hazardCd-=dt;if(survival.hazardCd<=0){const defenders=[hero,...botHeroes.filter(b=>b.team==='blue'&&!b.dead)],target=defenders[Math.floor(Math.random()*defenders.length)];if(target)createDangerZone(target.x,target.y,siegeDifficulty==='nightmare'?125:90,1.05,siegeDifficulty==='nightmare'?72:45,'Разлом осады','slow',siegeDifficulty==='nightmare'?'#ff3d70':'#c678ff');survival.hazardCd=siegeDifficulty==='nightmare'?8:14}}const core=nexuses.find(n=>n.team==='blue');if(core&&core.hp<core.maxHp)survival.perfect=false;const attackers=minions.filter(m=>m.team==='red'&&!m.dead&&m.hp>0);if(attackers.length)return;if(wave>survival.cleared){survival.cleared=wave;survival.score+=wave*100+(wave%5===0?500:0);hero.gold+=120+wave*12;for(const ally of [hero,...botHeroes.filter(b=>b.team==='blue')])if(!ally.dead)ally.hp=Math.min(ally.maxHp,ally.hp+ally.maxHp*.2);feed(`Волна ${wave} отражена · +${120+wave*12} золота`,'blue');waveTimer=wave>=survival.target?0:5;if(wave<survival.target&&wave%3===0){setTimeout(openFortificationChoice,250);return}}if(wave>=survival.target){survival.finished=true;survival.score+=survival.perfect?1500:0;announce('ЯДРО УДЕРЖАНО · ОБОРОНА ЗАВЕРШЕНА');setTimeout(()=>endGame(true),900);return}waveTimer-=dt;if(waveTimer<=0){spawnWave();waveTimer=9999}}
