function updateVisionGameplay(dt){
  hero.controlWardCd=Math.max(0,hero.controlWardCd-dt);
  if(hero.controlWardCharges<=0&&hero.controlWardCd<=0)hero.controlWardCharges=1;
  hero.wardRecharge=Math.max(0,hero.wardRecharge-dt);
  if(hero.wardRecharge<=0&&hero.wardCharges<hero.wardMax){hero.wardCharges++;hero.wardRecharge=hero.wardRechargeBase;showToast('Новый тотем обзора готов');}
  hero.sweeper=Math.max(0,hero.sweeper-dt);hero.sweeperCd=Math.max(0,hero.sweeperCd-dt);
  for(const w of wards){
    if(w.dead)continue;
    w.life=Math.max(0,w.life-dt);
    w.revealed=Math.max(0,(w.revealed||0)-dt);
    w.disabled=Math.max(0,(w.disabled||0)-dt);
    if(w.life<=0){w.dead=true;continue}
    if(w.team==='red'&&hero.sweeper>0&&!w.disabled&&Math.hypot(w.x-hero.x,w.y-hero.y)<=330){w.revealed=2.2;w.disabled=hero.sweeper;floatText(w.x,w.y-28,'ТОТЕМ ОБНАРУЖЕН','#ff8ca2');particles.push({x:w.x,y:w.y,life:.45,max:.45,type:'wardPulse',color:'#ff7085'});}
    if(w.team==='red'&&!w.disabled&&wards.some(c=>c.team==='blue'&&c.kind==='control'&&wardActive(c)&&Math.hypot(c.x-w.x,c.y-w.y)<=wardVisionRadius(c))){w.revealed=1.1;w.disabled=Math.max(w.disabled||0,.35);if(Math.random()<dt*2)floatText(w.x,w.y-28,'ОБНАРУЖЕН','#d58aff');}
  }
  if(hero.sweeper>0){for(const w of wards)if(w.team==='red'&&wardActive(w)&&Math.hypot(w.x-hero.x,w.y-hero.y)<=330)w.revealed=Math.max(w.revealed,1)}
  // Support/objective bots periodically establish practical vision near river and objectives.
  for(const b of botHeroes){if(b.dead||b.wardCd>0)continue;b.wardCd=26+Math.random()*12;const spots=[[1135,735],[1465,1065],[980,980],[1620,760],[760,1180],[1760,1220]];const spot=spots[(Math.floor(time/20)+b.lane+(b.team==='red'?3:0))%spots.length],x=spot[0]+(b.team==='red'?35:-35),y=spot[1]+(b.team==='red'?20:-20);if(Math.hypot(b.x-x,b.y-y)>850)continue;const existing=wards.find(w=>w.team===b.team&&wardActive(w)&&Math.hypot(w.x-x,w.y-y)<120);if(existing)continue;wards.push({x,y,life:90,team:b.team,kind:'ward',name:'ТОТЕМ ОБЗОРА',r:10,hp:3,maxHp:3,dead:false,revealed:b.team==='blue'?99:0,disabled:0,owner:b.name});particles.push({x,y,life:.55,max:.55,type:'wardPulse',color:b.team==='blue'?'#72e6a4':'#ff7085'});}
  if(wards.length>40)wards.splice(0,wards.length-40);
  updateVisionControl();
}
function updateStructureDebris(dt){for(let i=structureDebris.length-1;i>=0;i--){const d=structureDebris[i];d.life-=dt;if(d.life<=0){structureDebris.splice(i,1);continue}d.vy+=260*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.rot+=d.vr*dt;if(d.y>WORLD.h+80)structureDebris.splice(i,1)}if(structureDebris.length>80)structureDebris.splice(0,structureDebris.length-80)}
function drawStructureDebris(){for(const d of structureDebris){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.globalAlpha=Math.max(0,Math.min(1,d.life/.45));ctx.fillStyle=d.color;ctx.fillRect(-d.size/2,-d.size/3,d.size,d.size*.66);ctx.strokeStyle='#d4e1df55';ctx.lineWidth=1;ctx.strokeRect(-d.size/2,-d.size/3,d.size,d.size*.66);ctx.restore()}}
