function drawTeamfightSilhouettes(){
  ctx.save();
  for(const u of [hero,enemy,...botHeroes]){
    if(!u||u.dead||u.hp<=0)continue;
    if(u.team==='red'&&!visibleToBlue(u.x,u.y))continue;
    const r=(u.r||22)+7, ally=u.team===hero.team, selected=hero.target===u;
    const color=selected?(ally?'#63e6ff':'#ffd45d'):(ally?'#39d7ff':'#ff5c70');
    ctx.globalAlpha=selected?.30:.13;
    ctx.fillStyle=color;
    ctx.beginPath();ctx.arc(u.x,u.y,r,0,Math.PI*2);ctx.fill();
    ctx.globalAlpha=selected?.9:.5;
    ctx.strokeStyle=color;ctx.lineWidth=selected?3:2;
    ctx.setLineDash(selected?[7,5]:[3,7]);
    ctx.beginPath();ctx.arc(u.x,u.y,r,0,Math.PI*2);ctx.stroke();
    ctx.setLineDash([]);
    if(selected){
      ctx.globalAlpha=.75;ctx.beginPath();
      ctx.moveTo(u.x-r-8,u.y);ctx.lineTo(u.x-r-1,u.y);
      ctx.moveTo(u.x+r+1,u.y);ctx.lineTo(u.x+r+8,u.y);
      ctx.stroke();
    }
  }
  ctx.restore();
}

