    title=names[convergence.objective]||'КОНВЕРГЕНЦИЯ'; timer=`${Math.max(0,Math.ceil(convergence.objectiveTimer))}с`;
    const b=Math.round(convergence.blue),r=Math.round(convergence.red);lead=b===r?'РАВНЫЙ СЧЁТ':b>r?'СИНИЕ ВПЕРЕДИ':'КРАСНЫЕ ВПЕРЕДИ';detail=`${b} : ${r} · ${lead}`;
